quests[71032] = { id = 71032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Spitzenjäger", sourceObjective = "Euer Ruhm ist unübertroffen, Champion. Es gibt noch eine letzte Technik, die ich Euch beibringen will. Keine Beute, ganz gleich wie mächtig, wird sich gegen Euch behaupten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[71034] = { id = 71034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Ooh, ein neues Artefakt. Ich werde es ins Register eintragen und anmerken, dass Ihr es gespendet habt. \n\n<Katalogisiererin Jakes macht eine Notiz im Register.> \n\nErledigt! Macht weiter so!" }
quests[71035] = { id = 71035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehrere Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Seht Euch die ganzen Artefakte an! Das könnte einen Moment dauern. \n\n<Katalogisiererin Jakes macht hastig einige Notizen im Register.> \n\nErledigt! Und jetzt fort mit Euch! Kommt wieder, wenn Ihr mehr für mich habt!" }
quests[71036] = { id = 71036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Ooh, ein neues Artefakt. Ich werde es ins Register eintragen und anmerken, dass Ihr es gespendet habt. \n\n<Katalogisiererin Jakes macht eine Notiz im Register.> \n\nErledigt! Macht weiter so!" }
quests[71037] = { id = 71037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehrere Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Seht Euch die ganzen Artefakte an! Das könnte einen Moment dauern. \n\n<Katalogisiererin Jakes macht hastig einige Notizen im Register.> \n\nErledigt! Und jetzt fort mit Euch! Kommt wieder, wenn Ihr mehr für mich habt!" }
quests[71038] = { id = 71038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtrophäe", progress = "Was habt Ihr für mich, Fremdling?", completion = "Der Klan Shikaar erkennt eine großartige Jagdtrophäe, wenn er sie sieht. Das wird Euch viel Gunst in unseren Augen einbringen." }
quests[71039] = { id = 71039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Jagdtrophäen", progress = "Was habt Ihr für mich, Fremdling?", completion = "Nur die größten Jäger können so viele großartige Jagdtrophäen vorweisen. Ihr ehrt die Jagd." }
quests[71040] = { id = 71040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Totems", progress = "Seid Ihr hier, um unsere Totems zurückzubringen?", completion = "Ah! Unsere Totems sind uns sehr wichtig. Ihr habt unseren Dank dafür, dass Ihr sie zurückgebracht habt, Jungspund." }
quests[71041] = { id = 71041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele gestohlene Totems", progress = "Seid Ihr hier, um unsere Totems zurückzubringen?", completion = "Es gibt zu viele auf diesen Inseln, die unser Volk ausnutzen. Unsere Totems zu verlieren ist, als würden wir einen Teil von uns selbst verlieren. Unser Erbe! Ihr habt unseren Dank dafür, dass Ihr sie zurückgebracht habt, Jungspund." }
quests[71042] = { id = 71042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Relikt der Titanen", progress = "Habt Ihr ein Relikt der Titanen gefunden?", completion = "Unglaublich! Dieses Relikt ist perfekt erhalten. Ich werde es sofort untersuchen.\n\nEure Bemühungen sind mehr als willkommen! Ich werde nicht vergessen, vor dem Valdrakkenabkommen gut von Euch zu sprechen.\n\nAlso, wo war ich? Ja, das passt perfekt hier hin..." }
quests[71043] = { id = 71043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Relikte der Titanen", progress = "Was habt Ihr heute für mich?", completion = "Wie habt Ihr so viele davon gefunden? Das ist eine wahrhafte Schatzkammer an Relikten! Eines Tages MÜSST Ihr mir Euer Geheimnis verraten.\n\nIhr habt unser Wissen über die Titanen einmal mehr erheblich vergrößert. Das Valdrakkenabkommen wird Euch wahrhaft bewundern!" }
quests[71053] = { id = 71053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsiedlertötungsquest", description = "Hilfe! Diese Hasen verschlingen mein Fleisch! Bitte, tötet sie, bevor sie uns alle töten!" }
quests[71058] = { id = 71058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtung des Windes", sourceObjective = "{name}, Ihr seid Drachenreiter, oder? Ihr zeigt großes Potenzial als Verbündeter. \n\nIch möchte Euch das geben, um unser wachsendes Bündnis zu feiern. Und wo das herkommt, gibt es noch viel mehr, versprochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[71060] = { id = 71060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfschmuck", sourceObjective = "Eure Taten ehren Euer Volk, werter {name}. Bitte, nehmt diesen Helm als Anerkennung für alles, was Ihr für uns tut. \n\nUnd natürlich würde ich liebend gerne mit Euch handeln, falls Ihr mehr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71066] = { id = 71066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktive Kuriosität", sourceObjective = "{name}, Ihr habt Glück. Einer unserer Handwerker hat Schuhe hergestellt, die Ihr vielleicht brauchen könnt. Weiß der Himmel, warum, aber Euer Dienst für unseren Klan hat mindestens einen von uns inspiriert. \n\nAber so sehr ich auch will, ich kann sie Euch nicht einfach schenken, da es sehr teuer war, auch nur ein einzelnes Paar Eures ungewöhnlichen Schuhwerks herzustellen. Aber sie stehen bereit, falls Ihr sie benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71067] = { id = 71067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeifende Steine", sourceObjective = "Drachenreiter! Die Aylaag wissen, dass es schwierig sein kann, ihr Lager zu finden. Aber Ihr kennt sie ja: Sie begrüßen jeden, der ihre Wege respektiert.\n\nEiner ihrer Nomaden hat diese Windsteine vorbeigebracht, die sie für Euch hergestellt haben. Sie sind nicht sehr mächtig verzaubert, aber sie bringen Euch in das Lager der Aylaag. Ein paar Mal zumindest. Wenn die Verzauberung nachlässt, können sie bestimmt mehr davon herstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[71073] = { id = 71073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantel der Freundschaft", sourceObjective = "Mein Freund! Wie schön, Euch wiederzusehen. Ich habe ein neues Geschenk für Euch!\n\nBitte, nehmt es, und meine Glückwünsche mit dazu. Aber sagt Huseng nicht, dass ich es Euch einfach so gebe. Er wollte, dass ich Euch etwas dafür berechne!", sourceObjectiveStatus = "unverified-source-field" }
quests[71074] = { id = 71074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde mit Wind und Schwingen", sourceObjective = "Ihr kommt gerade rechtzeitig, Drachenreiter. Ich habe eine spezielle neue Anschaffung von den Ohn'ir. \n\nUnsere Klans liegen so weit voneinander entfernt, dass wir häufig auf Ohuna zurückgreifen, um dringende Nachrichten zu verschicken. Hiermit könnt Ihr unsere Briefadler rufen, wo auch immer Ihr gerade seid. Sie sind nicht die Schnellsten, aber verlässlich.\n\nIch würde normalerweise ja verhandeln, aber das ist eine zu wichtige Gabe. Ihr könntet sie dringend brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71075] = { id = 71075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Anmut verstehen", sourceObjective = "Mein Freund, Ihr seid zurück! Wir haben gerade darüber gesprochen, wie nützlich Ihr seid!\n\nHier, nehmt dieses Geschenk. Es ist das Mindeste, was wir für einen Verbündeten tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[71079] = { id = 71079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt zum Punkt", sourceObjective = "Sie haben Euch also endlich zu mir geschickt, wie? Ausgezeichnet! \n\nIch habe viele Waffen für Euch vorrätig. Normalerweise würde ich um meine Waren handeln, aber heute möchte ich einfach Eure Taten für mein Volk ehren.\n\nSagt nur Huseng nichts davon. Er würde es mir nie verzeihen, wenn er wüsste, dass ich etwas verschenke. Und wenn auch nur einem Drachenreiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[71083] = { id = 71083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erwartetes unerwartetes Geschenk", sourceObjective = "Drachenreiter! Einige unserer Waren fehlen.\n\n. Ich würde meine Hufe verwetten, dass Rondare wieder zu freundlich war. Ich habe ihr deutlich gesagt, dass sie nicht einfach so Waren verschenken soll. Ich werde wohl noch ein ernstes Gespräch mit ihr führen müssen.\n\n<Huseng murmelt vor sich hin, dann fällt ihm etwas ein.>\n\nOh, fast hätte ich es vergessen. Ich wollte Euch das hier geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[71085] = { id = 71085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repräsentation zählt", sourceObjective = "Drachenreiter! Eure Taten sind seit mehreren Monden das Gesprächsthema Nummer eins bei sämtlichen Klans. \n\nUnd sie alle haben mich gebeten, Euch ein Banner in den Farben ihrer Klans herzustellen, damit Ihr sie auf dem Schlachtfeld repräsentieren könnt. Das Problem ist nur, ich kann Euch nur eines davon schenken. Huseng ist mir auf der Spur.\n\nWelches wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[71089] = { id = 71089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Horn", sourceObjective = "Mein Freund, die Shikaar haben mich gebeten, Euch eines ihrer rituellen Jagdhörner anzubieten. Sie sagten, sie wären ausschließlich für Euch und ich sollte sie nicht benutzen. \n\nPah! Ich bin ein ausgezeichneter Jäger. Vielleicht der beste, den sie je sehen werden! Sie wissen es nur noch nicht.\n\n<Huseng lacht.>\n\nAlso bitte, hier. Der Rest steht zum Verkauf, falls Ihr mehr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71090] = { id = 71090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Herzen für die Herzen", sourceObjective = "Ah, Drachenreiter. Ich habe etwas für Euch.\n\n<Huseng hält eine Brustrüstung in Eurer Größe hoch.>\n\nWir mussten sie für Euch ein wenig, äh, enger machen. Sie ist gut gefertigt. Zu gut, um sie einfach herzuschenken. Aber ich kann sie Euch für den Materialpreis überlassen. \n\nIhr habt Euch als Verbündeter der Maruuk bewiesen. Es ist an der Zeit, dass man es Euch auch ansieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[71091] = { id = 71091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die höchste Ehre", sourceObjective = "Mein Freund, Ihr verteidigt diese Ebenen an der Seite meines Volkes und helft jedem unserer Klans aus, ohne zu zögern. Ihr seid nicht mehr länger ein Fremdling, sondern ein vertrautes Gesicht für die Zentauren.\n\nUm dieses Bündnis zu ehren, verleihe ich Euch den Titel der Khanswache und überreiche Euch dieses Geschenk. Mögt Ihr den Namen der Maruuk mit Stolz tragen, wohin auch immer es Euch verschlägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71093] = { id = 71093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis von Tyr: Geheimnisse der Vergangenheit", description = "Damit Raszageth die anderen Inkarnationen nicht befreien kann, müssen wir die Macht der Aspekte wiederherstellen.\n\nUnglücklicherweise sind die Titanen mit anderen Dingen beschäftigt und Hüter Tyr ist schon lange tot.\n\nKönigin Alexstrasza hat jedoch einen Plan vorgebracht. In den Tiefen des Ödlands liegt eine Titanenanlage namens Uldaman. Anscheinend haben Verbündete Tyrs dort eine Scheibe mit seinen Erinnerungen versteckt.\n\nJedoch wurde diese Anlage angeblich von Troggs überrannt. Sammelt Eure Verbündeten und begebt Euch nach Uldaman. Beschlagnahmt die Scheibe im Namen der Drachenkönigin!", sourceObjective = "Geht nach Uldaman: Vermächtnis von Tyr im Ödland und bergt die Scheibe.", sourceObjectiveStatus = "unverified-source-field" }
quests[71094] = { id = 71094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helfen ist unser Weg!", description = "Hallöchen!\n\nSeid Ihr auch hier, um zu helfen? Ihr seht sehr hilfreich aus!\n\n<Heleth deutet auf den verletzten Dracthyr.>\n\nDer da drüben hat sich beim Versuch, hier hochzufliegen, den Flügel verletzt! Er sieht aus wie einer von den Bösen von da unten, aber ich habe keine Angst vor ihm! Ich werde ihm so oder so helfen, weil wir das nun mal so machen!\n\n<Heleth strafft die Schultern.>\n\nIch werde auf ihn aufpassen, während Ihr ein paar Verbände sucht!", sourceObjective = "Findet Verbände im Turm über dem Kobaltkonvent, um Venderthvan zu heilen.", progress = "Endlich! Mehr Leute zum Spielen!", completion = "Wir werden diesem Bösen so gut es geht helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[71095] = { id = 71095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klaue in Not", description = "Mal sehen, wie wir diesem Kerl helfen können!\n\n<Heleth lehnt sich zu Euch vor und flüstert.>\n\nKeine Sorge, wir werden ihn nichts klauen lassen oder so. Lasst uns nur etwas Spaß haben!\n\nEs ist ewig her, dass jemand hergekommen ist, um nach uns zu sehen. Uns ist SO langweilig!\n\n<Heleth zwinkert Euch zu.>\n\nWarum fragt Ihr ihn nicht, was er will?", sourceObjective = "Fragt Venderthvan, wie Ihr ihm helfen könnt, und tut, was er sagt.", progress = "Na los, {race}, macht die ganze Arbeit für mich. Es wird ein Kinderspiel, Euch das Artefakt abzunehmen, wenn sich die Gelegenheit ergibt.", completion = "Das sieht vielversprechend aus. Gebt es mir.\n\n...Was meint Ihr damit, Ihr werdet es mir nicht geben?", sourceObjectiveStatus = "unverified-source-field" }
quests[71096] = { id = 71096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klaue zweifellos", description = "<Venderthvan reibt sich die Augen und stöhnt vor Schmerzen.>\n\nNa gut. Wenn Ihr es mit nicht gebt, könnt Ihr selbst herausfinden, wie es funktioniert.\n\nIch werde es Euch abnehmen, wenn Ihr fertig seid. Mit Gewalt, wenn es sein muss.\n\nAlso nur zu. Schüttelt es oder so.", sourceObjective = "Versucht, das Artefakt zu aktivieren.", progress = "<Venderthvan ist von der Spielzeugente abgelenkt, die Nezzie ihm zeigt.>", completion = "Was? Oh, stimmt. Das Arkana.", sourceObjectiveStatus = "unverified-source-field" }
quests[71097] = { id = 71097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Klaue", description = "Also gut, Ihr habt das Artefakt aufgeladen. Dann aktiviert es.\n\nUnd hört auf, mich so anzusehen. Tut nicht so, als wärt Ihr nicht neugierig, ob es funktioniert.\n\nSchüttelt es noch einmal, entfernt Euch langsam und lasst es mich zu Ende bringen.", sourceObjective = "Aktiviert das Artefakt im Turm über dem Kobaltkonvent und beobachtet Venderthvans Handlungen.", completion = "Genug... genug!\n\nDas geht zu weit.\n\nNehmt nur das Artefakt, bevor ich es mir anders überlege und meine Meinung ändere!", sourceObjectiveStatus = "unverified-source-field" }
quests[71135] = { id = 71135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeklärte Angelegenheiten", description = "Wenn ich eines von meiner Zeit in der Wildnis gelernt habe, dann dies: Dass man sich um das Böse kümmert, wenn man es findet, und dass man seine Knochen brechen und seine Wurzeln ausreißen muss, damit es nicht weiterwächst. Denn dann wird es schwerer zu töten.\n\nDiese Berge leiden schon unter Frostbiss' Existenz, seit ich ein kleiner Welpe war wie Ihr. Und es wird nur schlimmer werden, wenn er die volle Kontrolle über den Schneebalgstamm erringt.\n\nIch hätte vor langer Zeit etwas gegen ihn unternehmen müssen, und nun sind wir die Einzigen, die diesen Fehler wiedergutmachen können.", sourceObjective = "Stellt Frostbiss am Schneebalglager im Azurblauen Gebirge.", progress = "Wir können nicht ruhen, bevor Frostbiss und die Schneebalggnolle erledigt sind.", completion = "Lasst uns das nie wiederholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71138] = { id = 71138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Rusza'thar-Vorstoß", description = "Ein Expeditionsmitglied hat berichtet, dass auf einem Ausguck auf den Ebenen von Ohn'ahra ein inaktiver Stein gesichtet wurde.\n\nBereit für ein Abenteuer?", sourceObjective = "Findet das inaktive Portal beim Rusza'thar-Vorstoß auf den Ebenen von Ohn'ahra.", progress = "Worauf wartet Ihr?", completion = "Ihr habt es schon wieder ans Laufen gebracht? Das ging ja fix!\n\nIch werd dieses Gefäß hier bei mir behalten. Wie's scheint, knistert da noch etwas Energie drin herum!\n\nMan weiß ja nie, ob wir sie noch mal brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71139] = { id = 71139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtendes arkanes Juwel", description = "<Dieses Juwel scheint sehr mächtig zu sein. Es verströmt ein unheimliches Licht.\n\nVielleicht wäre es das Beste, es den Kirin Tor zu bringen, damit es sicher verwahrt werden kann.>", sourceObjective = "Bringt das leuchtende arkane Juwel zu Noriko der Allererinnernden im Lager Antonidas.", completion = "Seht Euch dieses Juwel an! Ich werde dafür sorgen, dass es sofort zur Untersuchung nach Dalaran gebracht wird.\n\nHier, nehmt das für Eure Bemühungen. Wir haben es vor Kurzem bei einer anderen Ausgrabung gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[71140] = { id = 71140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei und zwei zusammen", sourceObjective = "Besiegt Bakhushek in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[71141] = { id = 71141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasse Kiemen", description = "Kad'irsza ist leichtsinnig, aber sie kennt ihre Krabben. Die Gorlocs sind zu weit gegangen!\n\nIch habe bemerkt, dass die Gorlocs für alles zu Gurblbrblr gehen. Vor allem erklärt er ihnen, wie man Krabben fängt. Das darf nicht so weitergehen, weder für das Gleichgewicht des Lebens noch für die Sicherheit derjenigen, die es pflegen.\n\nBesiegt Gurblbrblr. Nehmt ihnen die Möglichkeit, sich jenseits dies Flusses auszubreiten!", sourceObjective = "Tötet Gurblbrblr den Eindringling am Klippensturzlager.", completion = "Gut. Jetzt werden die Gorlocs keine Mittel mehr haben, um all diese Krabben zu fangen.\n\n...Und Ihr habt mehr erreicht, als nur meine Krabben zu beschützen, {name}. Ihr habt auch Kad'irsza beschützt. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[71143] = { id = 71143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenschlächter", description = "Toll! Immer weiter so, <Soldat/Soldatin>!\n\nTötet ein paar mehr von der Horde, dann werdet Ihr in die Geschichtsbücher der Allianz eingehen.\n\nAber das wird nicht ganz leicht. Die Horde hat ein Kopfgeld auf Euch ausgesetzt, also seid vorsichtig!\n\nFür die Allianz!", sourceObjective = "Während Ihr von der Horde gejagt werdet, tötet 10 ihrer Mitglieder, ohne zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[71144] = { id = 71144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzschlächter", description = "Ja! Weiter so, tötet diese Allianztölen!\n\nWenn Ihr noch ein paar Allianzler tötet, könntet Ihr einen neuen Rekord aufstellen, {class}.\n\nAber das wird nicht leicht, denn die Allianz hat einen Preis auf Euren Kopf ausgesetzt! Passt auf Euch auf!\n\nFür die Horde!", sourceObjective = "Während ein Kopfgeld auf Euch ausgesetzt ist, tötet 10 Mitglieder der Allianz, ohne zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[71145] = { id = 71145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Großmeister", sourceObjective = "Besiegt Flicki in einem Haustierkampf", sourceObjectiveStatus = "unverified-source-field" }
quests[71146] = { id = 71146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Der Forscher-in-Ausbildung gibt Euch eine knappe zusammengerollte Notiz. Sie scheint von einem alten Freund zu stammen, Thaelin Schwarzamboss, der Euch um Hilfe bittet.\n\nBevor es davonhuscht, streckt das kleine Tier Euch eine Hand entgegen, als würde es um eine Belohnung bitten. Kurz darauf ertönt ein schriller Schrei, als die seltsame Kreatur mit leeren Händen davonprescht.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Ah, Ihr kehrt für ein neues Abenteuer zurück und was soll ich sagen... Euch habe ich am liebsten!\n\nOh, aber das bleibt zwischen uns. Die Anderen sollen nicht denken, sie wären mir nicht auch die Liebsten!", sourceObjectiveStatus = "unverified-source-field" }
quests[71148] = { id = 71148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Das merkwürdige Tierchen vor Euch hält Euch eine Notiz entgegen, gezeichnet und gesiegelt von der Drachenschuppenexpedition.\n\nVielleicht ein Hilferuf von einem berühmten Forscher.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Was haben wir denn hier? Es ist mein abenteuerlustigster... ähm... Abenteurer!\n\nLust auf noch mehr Erkundungen?", sourceObjectiveStatus = "unverified-source-field" }
quests[71149] = { id = 71149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Überaschenderweise hat der Bote Euch diesmal weder ein Säckchen noch eine Notiz gebracht, sondern einen Gegenstand aus Thaelins persönlicher Sammlung.\n\nBei genauerer Betrachtung findet Ihr dennoch eine Nachricht von Thaelin, der einmal mehr um Eure Unterstützung bittet.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Ihr könnt einfach nicht genug kriegen, was?\n\nSchön, Euch zu sehen, {name}! An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[71150] = { id = 71150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Das Pergament verströmt einen unangenehmen, schimmligen Geruch. Nachdem Ihr Euch gesammelt habt wird Euch klar, dass Thaelin Eure Unterstützung auf der Suche nach Antworten zu seinen jüngsten Funden braucht.\n\nIhr fragt Euch nur, was Ihr nun mit dem unerträglich stinkenden Pergament machen sollt.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Ach, Ihr habt mich erschreckt! Hätte nicht gedacht, dass Ihr so schnell kommt.\n\nIhr seid in der Stimmung für Erkundungen, wie ich sehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[71151] = { id = 71151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Der Brief ist sauber, unzerknittert und trägt das Siegel der Drachenschuppenexpedition.\n\nThaelin Schwarzamboss verlangt Eure Anwesenheit.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Der berühmte Forscher kehr zurück! Ich hab mich ganz schön an unsere gemeinsame Zeit gewöhnt, {name}.\n\nWas meint Ihr? Auf ein letztes Hurra?", sourceObjectiveStatus = "unverified-source-field" }
quests[71152] = { id = 71152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Haupthalle", description = "Nun, da wir auf die Überbrückungskonsolen zugegriffen haben, sollten wir an dieser Barriere vorbeikommen.\n\nTrefft mich in der Haupthalle, dann erledigen wir das!", sourceObjective = "Trefft Euch mit Toddy in der Haupthalle.", completion = "Die ganze harte Arbeit zahlt sich bald aus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[71153] = { id = 71153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltquests, Bonusziele und Szenarien, oje", description = "Unterstützt die Tortollaner, indem Ihr 3 Weltquests abschließt.", sourceObjective = "Schließt 3 Weltquests der Tortollaner ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[71154] = { id = 71154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krallenwurf: Schießen 1x1" }
quests[71155] = { id = 71155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Azurblaue Gewölbe", description = "Wir haben ein Problem, {name}.\n\nUnter den Azurarchiven ruht das Azurblaue Gewölbe. Ich habe im Laufe meines Lebens so manche wichtige und gefährliche magische Kuriosität darin eingelagert.\n\nJetzt ist eine große Gruppe von Splitterflammen ins Gewölbe eingebrochen, in der festen Überzeugung, dass es wertvolle Geheimnisse birgt.\n\nBitte, Ihr müsst hineingehen und diesen törichten Überfall aufhalten, sonst entfesseln sie Gefahren, die sie nicht begreifen können.\n\nDiese Diebe ahnen nicht, was im Gewölbe lauert.", sourceObjective = "Haltet die Splitterflammen im Azurblauen Gewölbe auf.\n\nIhr könnt das Azurblaue Gewölbe allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", progress = "Gebt im Gewölbe acht auf Euch.", completion = "Zehntausend Jahre versuchte ich hinauszuzögern, wovon ich in meinem Herzen fürchtete, dass es das unausweichliche Ende meines Kindes bedeuten würde.\n\nMalygos und ich hofften, dass wir eines Tages ein Heilmittel finden würden. Obschon dieser Tag nie kam, würde ich es doch immer wieder so machen.\n\nWir dürfen die Hoffnung nie aufgeben, selbst wenn die Chancen verschwindend gering zu sein scheinen.\n\nMein einziger Trost ist das Wissen, dass mein Kind nun zumindest mit der wahren Sindragosa und dem wahren Malygos wiedervereint ist.\n\nNun geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[71156] = { id = 71156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellensorgen" }
quests[71157] = { id = 71157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Himmelhochobservatorium", description = "Einige unserer Entdecker aus dem Norden berichten, dass sich ein weiterer dieser Steine hoch oben auf dem Turm im Nordosten befindet.\n\nIch hab gehört, dass es ziemlich schwierig ist, da oben ranzukommen, aber ich wette, dass Ihr einen Weg findet!", sourceObjective = "Findet das inaktive Portal am Himmelhochobservatorium an der Küste des Erwachens.", progress = "Wie sieht es aus?", completion = "Der Gipfelstürmer ist zurück!\n\nHoffe, es hat nicht allzu viel Mühe gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[71160] = { id = 71160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbombe" }
quests[71161] = { id = 71161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Vakthros", description = "Wir haben einen Bericht von einem weiteren der inaktiven Steine in der winterlichen Region im Südosten erhalten.\n\nBevor Ihr jetzt ganz aufgeregt werdet, solltet Ihr wissen, dass nicht viele freiwillig da hingehen würden, aber wenn Ihr Lust auf ein möglicherweise tödliches Abenteuer habt, ist es genau das Richtige!\n\nSeid Ihr schon überzeugt? Gut!\n\nWerft Euch in Eure wärmsten Klamotten. Geht anschließend nach Osten, bis der kalte Wind Euch an der Nase kitzelt, und geht dann immer weiter. Ihr werdet wissen, dass Ihr in der Nähe seid, wenn Euer Atem steif und Eure Knochen kalt werden.", sourceObjective = "Findet das inaktive Portal auf dem Turm in Vakthros im Azurblauen Gebirge.", progress = "Haltet Ihr Euch warm?", completion = "Bisschen kalt, oder?\n\nAber jetzt, da das erledigt ist, was steht als Nächstes an?", sourceObjectiveStatus = "unverified-source-field" }
quests[71162] = { id = 71162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Algeth'era", description = "Neuer Stein, neuer Turm.\n\nAm besten macht Ihr Euch auf den Weg. Das wird eine ordentliche Wanderung und gefährlich noch dazu! Zumindest, wenn man ihren Entdeckern glauben kann.\n\nSeid Ihr bereit?", sourceObjective = "Findet das inaktive Portal auf dem Turm in Algeth'era in Thaldraszus.", progress = "Auf Euch ist immer Verlass!", completion = "Ich frage mich, wann diesem Gefäß der Saft ausgeht. Hm, vielleicht frage auch nur ich mich das.\n\nWas ist das überhaupt für ein Ding?\n\n<Thaelin schüttelt das Gefäß, aber es macht keine Geräusche.>", sourceObjectiveStatus = "unverified-source-field" }
quests[71164] = { id = 71164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Verbände" }
quests[71165] = { id = 71165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Grenze des Äons", description = "In weiter Ferne, in den Bergregionen von Thaldraszus gibt es ein kleines Gasthaus, das dort am Berghang steht. Gleich hinter dem Eingang liegt ein längst vergessener, inaktiver Stein.\n\nWas meint Ihr? Lust auf ein neues Abenteuer, {name}?", sourceObjective = "Findet das inaktive Portal an der Grenze des Äons in Thaldraszus.", progress = "Ich würde gern hier sitzen, und mich mit Euch unterhalten, aber wir haben Arbeit zu tun.", completion = "Eure abenteuerlustige Natur amüsiert mich!\n\nIch frage mich, wie viele dieser Dinger es da draußen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71166] = { id = 71166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die älteste Libelle", sourceObjective = "Besiegt Flunk in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[71178] = { id = 71178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Schattenzuflucht", description = "Unsere Expedition berichtet von einem inaktiven Stein bei den üppigen Hängen im Südwesten. Es ist ein gutes Stück entfernt, aber es lohnt sich, jemanden mit Eurer Kenntnis für die Untersuchung dort hinzuschicken.", sourceObjective = "Findet das inaktive Portal bei der Schattenzuflucht auf den Ebenen von Ohn'ahra.", progress = "Na? Nun macht schon!", completion = "Sieht aus, als hätte es funktioniert!\n\nIch bewahre das Gefäß auf, falls wir es nochmal brauchen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[71179] = { id = 71179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick zum Rundblick", description = "{name}, ich habe eine neue Aufgabe für Euch.\n\nEs gibt Berichte von Primalistenaktivitäten in der Nähe des Postens der Gelikyr, die unsere Kontrolle über Tyrhold gefährden.\n\nSprecht mit Kommandant Thadezus und seht zu, wie Ihr helfen könnt.", sourceObjective = "Sprecht mit Kommandant Thadezus am Rundblick der Gelikyr.", completion = "<Thadezus seufzt tief.>\n\nIhr sagt, Drine hat Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[71180] = { id = 71180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr müsst irgendwo anfangen", sourceObjective = "Besiegt Setimothes in einem Haustierkampf", sourceObjectiveStatus = "unverified-source-field" }
quests[71181] = { id = 71181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Grottenrelikte" }
quests[71182] = { id = 71182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivare auf Abwegen", description = "Ihr da, Dracthyr.\n\nZwei von Eurer Art haben die Archive südlich von hier durchsucht. Ich habe mich ihnen noch nicht vorgestellt und wüsste Eure Gesellschaft zu schätzen.\n\nFalls Ihr Zeit habt, können wir uns im oberen Archiv treffen.", sourceObjective = "Trefft Sindragosa im oberen Archiv der Azurarchive.", completion = "Ihr seid ein schreckhafter Haufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71191] = { id = 71191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut vernetzt", description = "Oh je, mein Fischernetz wurde von der Strömung davongetragen. <Seufz> Ich nutze nicht gerne Angelruten, wie meine Freunde...\nWenn Ihr zufällig mein Fischernetz irgendwo findet, bringt es doch bitte zurück.", sourceObjective = "Holt das Netz des bärbeißigen Fischers an den Eislöchern im Azurblauen Gebirge.\n\nIhr könnt nur ein zusätzliches Fischernetz pro Tag freischalten.", progress = "Konntet Ihr das Netz finden?", completion = "Ihr habt es gefunden! Aber leider zu spät, ich habe schon einen Ersatz von Tavio in Iskaara bekommen. Behaltet es ruhig, es eignet sich am besten, um Fische in diesen eisigen Gewässern zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71192] = { id = 71192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtierkontrolle", description = "Seid gegrüßt.\n\nIch habe nach einem geeigneten Platz gesucht, um ein paar Fischernetze auszulegen, aber die Watschlerpopulation in dieser Gegend ist zu hoch... Sie fressen die meisten kleinen Fische auf, bevor sie überhaupt erst dazu kommen, heranzuwachsen.\n\nIch habe ein paar Bildnisse gemacht, um zumindest ein paar dieser gefräßigen Vögel zu verscheuchen. Das wird uns dabei helfen, die üppigen Fischgründe der Drachenquellen zu erhalten.\n\nKönnt Ihr mir dabei helfen, sie aufzustellen?", sourceObjective = "Stellt die furchteinflößenden Bildnisse auf.\n\nIhr könnt nur ein zusätzliches Fischernetz pro Tag freischalten.", progress = "Habt Ihr ausreichend Bildnisse aufgestellt?", completion = "Gut gemacht, Freund! Ihr könnt jetzt gerne eine weiteres Fischernetz auslegen, es sollte genug für uns alle da sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[71193] = { id = 71193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwasserbedrohung", description = "Habt Ihr das gesehen? Unter Wasser! Ein riesiges, gepanzertes, hungriges Ungeheuer! Auf keinen Fall gehe ich mit meinem Netz an das Wasser, während so eine Monstrosität da lauert. Wenn Ihr wollt, könnt Ihr sie mit einer Handvoll ominöser Muscheln hervorlocken. Die sollten nicht zu schwer zu fangen sein.\n\nWenn Ihr Muscheln fangen wollt, müsst Ihr auf den Dracheninseln beim Angeln Eure Harpune von Iskaara parat haben.", sourceObjective = "Verwendet 5 ominöse Muscheln am Angelloch von Tyrhold, um eine riesige Unterwasserbestie anzulocken, und nehmt einen Beweis ihres Ablebens mit.\n\nIhr könnt nur ein zusätzliches Fischernetz pro Tag freischalten.", progress = "Ihr habt doch nicht etwa Angst vor riesigen Küstentieren, oder? Ich nämlich schon!", completion = "Würde es Euch was ausmachen, mir etwas Fleisch abzugeben? Vielen Dank, dafür zeige ich Euch den besten Ort zum Netzfischen hier in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[71194] = { id = 71194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frösche des Feuers", description = "Ich habe den perfekten Ort gefunden für ein Fischernetz. Ein Problem bekümmert mich jedoch... diese Hornstacheln. Ich bin mir ziemlich sicher, dass sie die Netze zerreißen werden, sobald sie ungestört sind. Was sollen wir tun?\n\nIch habe eine Idee. Wir behandeln unsere Lavafischnetze mit Eiszapfengebräu, um sie hitzeresistent zu machen. Wir müssen den Hornstacheln nur zu verstehen geben, sich von dem Geruch fernzuhalten.\n\nWerft ein Fläschchen Eiszapfengebräu auf einen Hornstachel und fügt ihm dann Schaden zu. Stellt nur sicher, dass Ihr sie nicht tötet. Sie können nicht lernen, wenn sie tot sind, oder?", sourceObjective = "Bringt ein paar Hornstacheln bei, Eiszapfengebräu zu meiden.\n\nIhr könnt nur ein zusätzliches Fischernetz pro Tag freischalten.", completion = "Gut gemacht! Ihr könnt gerne den Platz für das Fischernetz nutzen, es ist genug Platz für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[71195] = { id = 71195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerrückgrat zähmen leicht gemacht", description = "Ich schätze, das hier ist Lizis neuer Lieblingsplatz. Sie wollte nicht wirklich wieder heimkommen. Immerhin ist sie ein wildes Tier.\n\nIch muss zugeben... ich habe nicht mehr mit Meluun gesprochen, seit wir Lizi gerettet haben. Ich sehe ja ein, dass sie recht hatte, aber ich weiß nicht, wie ich mit ihr sprechen soll. Ich kann es ihr einfach nicht recht machen. Ich weiß, dass ich mich mehr um meine Ausbildung kümmern muss.\n\nMeluun macht ein Curry zum Dahinschmelzen, das Lizi bestimmt lieben würde. Könntet Ihr sie wohl danach fragen? Sie arbeitet normalerweise in ihrem Haus westlich der Quellen.", sourceObjective = "Holt Meluuns grünes Curry in den Quellen von Ohn'iri und 150 Vorräte der Dracheninseln.", progress = "Habt Ihr schon mit Meluun gesprochen?", completion = "Ich kann es bis hier riechen! Oh, bei den Vorfahren, Lizi wird so glücklich sein! Ich nehme das als ein Zeichen, dass Meluun mich noch nicht komplett aufgegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[71196] = { id = 71196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerrückgrat zähmen leicht gemacht", description = "Ich bin so froh, dass Lizi bei uns in Sicherheit ist.\n\nLeider heilen ihre Wunden aber langsamer als gedacht. Ich hoffe nur, die Magie, der sie ausgesetzt war, hat keine bleibenden Schäden hinterlassen.\n\nKönntet Ihr mir wohl helfen, Insektensekret zu sammeln? Ich weiß, es klingt unappetitlich, aber es ist die Basis von vielen Heilsalben.", sourceObjective = "Sammelt 20 Portionen fluoreszierende Flüssigkeit von Insekten auf den Dracheninseln sowie 150 Vorräte der Dracheninseln.", progress = "Seid Ihr mit mehr Sekret zurück? Es bricht mir das Herz, Lizi leiden zu sehen.", completion = "Ich trage das sogleich auf ihre Wunden auf. Damit sollte es ihr sofort besser gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71197] = { id = 71197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerrückgrat zähmen leicht gemacht", progress = "Lizi ist gesund, aber sie traut sich nicht, ihren Platz zu verlassen. In freier Wildbahn würde sie wohl pro Tag Pflanzen vom Gewicht eines Moschushirschen sammeln. Ich kann das unmöglich schaffen! Wir müssen sie aus dem Wasser holen und auf das Gras bringen.\n\nIch werde versuchen, sie herauszulocken, aber könntet Ihr mir in der Zwischenzeit beim Sammeln helfen? Ich habe gehört, dass es besonders nahrhafte faserreiche Blätter in den Smaragdgärten gibt. Bringt bitte so viele, wie ihr finden könnt!", completion = "Damit sollte sie erst einmal versorgt sein, bis sie sich selbst auf Futtersuche machen kann." }
quests[71198] = { id = 71198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerrückgrat zähmen leicht gemacht", progress = "Lizi geht es so viel besser. Sie springt wieder herum, als ob nichts gewesen wäre, und verspeist alles, was ihr vor die Nase kommt.\n\nHeute habe ich gelernt, dass Donnerrückgrate gern Fisch fressen, vor allem Piranhas! Wie faszinierend! In ihrer Heimat sorgen sie so dafür, dass die Piranhabestände nicht überhandnehmen.\n\nWürdet Ihr wohl welche angeln gehen? Aber passt auf Eure Fingerchen auf!", completion = "Diese Piranhas sehen wirklich... knusprig aus. Zum Glück gibt es Raubtiere, die sie mit Vergnügen fressen." }
quests[71199] = { id = 71199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerrückgrat zähmen leicht gemacht", progress = "Jeder ist neugierig, was Lizi betrifft, aber in Wahrheit fällt sie auf wie ein bunter Hund. Lizi streift jeden Tag weiter herum, als würde sie nach etwas suchen.\n\nSie ruht meistens im Schlamm am Wasser. Das geht schon, aber eigentlich bauen sich Donnerrückgrate Nester aus Gräsern.\n\nIch habe eine Idee, die noch besser ist als Gräser! Würdet Ihr mir helfen und Wolle auf den Ebenen sammeln? Dann webe ich ihr eine gemütliche Decke und was zum Spielen.", completion = "Perfekt! Damit machen wir ihr bestimmt eine Freude! Ich habe noch kein Tier kennengelernt, das weiche, kuschelige Dinge verschmäht." }
quests[71202] = { id = 71202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winziger Manageistnahkämpfer", sourceObjective = "Besiegt Arkantus in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[71205] = { id = 71205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassertuskarr" }
quests[71206] = { id = 71206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge des Sturmlings", sourceObjective = "Besiegt Sturmamu in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[71209] = { id = 71209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtier der Ebenen", sourceObjective = "Nehmt Lizis Zügel an.", completion = "Vergesst nicht, mal wieder zu Besuch zu kommen! Macht's gut, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[71210] = { id = 71210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Drachenfluchfestung!", description = "<Flatter lässt eine leicht angesengte Notiz in Eure Hand fallen.>\n\n{name}, die Obsidianausgestoßenen haben Geschichten über Euren Mut gehört. Unsere frühere Heimat, die Drachenfluchfestung, ist in die Hände der Djaradin gefallen. Wir können das nicht auf uns sitzen lassen. Helft uns, unser Land zurückzuerobern.\n\nBoss", sourceObjective = "Reist an die Küste des Erwachens und schließt Euch den Obsidianausgestoßenen bei der Belagerung der Drachenfluchfestung an.", progress = "Wir müssen die Festung einnehmen!", completion = "Die Schlacht ist gewonnen, doch der Krieg geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[71212] = { id = 71212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Brackenfelle" }
quests[71219] = { id = 71219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegbehüter auf Abwegen", description = "Scheinbar haben einige der jüngeren Wegbehüter in letzter Zeit ihre Pflicht vernachlässigt. \n\nWegbehüterin Nori hat mich gebeten, nach ihrer jüngeren Schwester Alvi zu sehen, die an der Mündung des Zeitenflusses stationiert ist. Ihre Leistung war in letzter Zeit wohl ungenügend.\n\nWenn Ihr nach Osten reist und zufällig auf Wegbehüterin Alvi trefft, erinnert sie bitte daran, wie wichtig ihre Position ist und dass ihre Schwester sich Sorgen um sie macht.", sourceObjective = "Findet Wegbehüterin Alvi.", completion = "Oh, du liebe Güte, Besuch! Verzeiht, ich bin gerade nicht ganz bei mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[71225] = { id = 71225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Winde verweht: Rhuzast" }
quests[71226] = { id = 71226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Steinschnecken", description = "Hilfe! Diese Hasen verschlingen mein Fleisch! Bitte, tötet sie, bevor sie uns alle töten!", sourceObjective = "Tötet 5 Hasen der Verdammnis auf dem Übungsplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[71227] = { id = 71227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftige Herausforderungen", description = "<Flatter flattert aufgeregt mit den Flügeln und lässt eine Nachricht und ein angesengtes Nagetier vor Eure Füße fallen.>\n\n<Drachenreiter/Drachenreiterin>! Euer Heldenmut ist weithin bekannt. Beweist Euch in luftigen Herausforderungen überall auf den Dracheninseln.\n\nSprecht mit einem Bronzezeithüter, um anzufangen.", sourceObjective = "Sprecht mit einem Bronzezeithüter, um mehr über die luftigen Herausforderungen zu erfahren.", completion = "Ein neuer Herausforderer? Willkommen!\n\nLuftige Herausforderungen sind Zeitrennen auf verschiedenen Strecken auf den ganzen Dracheninseln. Schlagt Bestzeiten, um Euren Rang zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71229] = { id = 71229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Ebenen", description = "<Roki drückt Euch eine Nachricht in die Hand.>\n\n{name}, Klan Aylaag hat Geschichten von Euren großen Taten gehört. Wir laden Euch ein, unseren Klan zu treffen und unsere Wege zu erfahren.\n\nHadari Khan", sourceObjective = "Sprecht mit Hadari Khan auf den Ebenen von Ohn'ahra.", completion = "Eure Hilfe ist willkommen, Drachenreiter. In unserem Lager gibt es viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[71230] = { id = 71230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelausrüstung der Tuskarr", description = "Hallo noch mal, {name}.\n\n<Rowie sieht sich um und summt ein Lied.>\n\nOh, stimmt! Tavio hat mir ein neues Netz gemacht und gesagt, sie könnte Euch auch eines machen. Sie kann auch andere Angelausrüstung machen, wenn Ihr das ganze Zeug zu ihr bringt.\n\nIhr solltet mit ihr reden.", sourceObjective = "Sprecht mit Tavio bei Iskaara im Azurblauen Gebirge.", completion = "Meine Familie ist dafür bekannt, die besten Netze und Harpunen herzustellen. Wenn Ihr mir die nötigen Materialien bringt, kann ich einige neue Werkzeuge für Euch herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71231] = { id = 71231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Jagd", description = "<Roki drückt Euch eine Nachricht in die Hand.>\n\n{name}, Klan Shikaar lädt Euch zur großen Jagd ein. Trefft Trainer Frodrum auf den Ebenen von Ohn'ahra.", sourceObjective = "Sprecht mit Trainer Frodrum auf den Ebenen von Ohn'ahra.", completion = "Drachenreiter! Eure Unterstützung wird die kommenden Jagden bereichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[71232] = { id = 71232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm der Dracheninseln", description = "Es gibt nach wie vor vieles, das getan werden muss, um den Dracheninseln zu helfen.\n\nIch würde Euch darum bitten, mit Koszaru zu sprechen. Er hat viele Informationen dazu, wer in diesen Landen Hilfe braucht.", sourceObjective = "Sprecht mit Koszaru in Valdrakken.", completion = "Gut, Euch zu sehen, {name}.\n\nEs gibt viele Quellen der Macht auf den Dracheninseln, man muss nur wissen, wo man suchen muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[71233] = { id = 71233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallendes Wasser", description = "Ich liebe Wasserfälle.\n\nWollt Ihr wissen, was besser ist als ein Wasserfall?\n\nZwei Wasserfälle!\n\nUnd das Einzige, was noch besser ist, als das... seht Euch Dreifälle im Westen an, dann erfahrt Ihr es!\n\nDie Gastwirtin dort ist ganz nett.", sourceObjective = "Sprecht mit Willa am Dreifällerundblick im Azurblauen Gebirge.", completion = "Willkommen am Dreifällerundblick!\n\nWir sind ziemlich weit oben, und überall strömt Wasser vorbei... Passt also auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[71234] = { id = 71234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten in jedem Winkel", description = "Ihr da, {race}.\n\nIhr seht weit gereist aus.\n\nMein Cousin Wayun hat einen Fang vom Walfängerwinkel mitgebracht und... merkwürdige Zeitgenossen erwähnt, die da ihr Lager aufgeschlagen haben.\n\nSie scheinen sich zu benehmen, aber würdet ihr nach Wayun sehen?\n\nEr ist schnell eingeschnappt.", sourceObjective = "Besucht den Walfängerwinkel im Azurblauen Gebirge.", completion = "Noch jemand?\n\nNa toll.", sourceObjectiveStatus = "unverified-source-field" }
quests[71235] = { id = 71235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldmagier", description = "Lok'tar, {race}.\n\nWenn Ihr Zeit habt, gibt es zwei Magier in der Nähe, die sicher Hilfe bei der Feldarbeit brauchen könnten.\n\nDieses Land ist in seinen besten Zeiten sehr gefährlich.\n\nUnd es sind nicht gerade die besten Zeiten.", sourceObjective = "Seht nach den Magiern der Kirin Tor in der Nähe von Slyvernsturz im Azurblauen Gebirge.", completion = "Wir brauchen Eure Hilfe nicht.\n\nAber wir nehmen sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[71238] = { id = 71238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rubinfestmahl!", description = "An alle aufstrebenden Kulinariker!\n\nStrebt Euer Herz nach den ultimativen Genüssen dieser Welt? Sucht Ihr nach Möglichkeiten für großartige Forschungen? Seid Ihr gewillt, Leib und Leben für vollkommen Fremde zu riskieren?\n\nDann sprecht mit dem unübertroffenen, angesehenen, weltberühmten Kochduo Rumiastrasza und Schnabuli! Zurzeit veranstalten sie das Rubinfestmahl in Valdrakken!", sourceObjective = "Sprecht mit den Köchen Rumiastrasza und Schnabuli beim Rubinfestmahl.", completion = "Ist es wegen der Poster? Haben sie tatsächlich funktioniert?", sourceObjectiveStatus = "unverified-source-field" }
quests[71239] = { id = 71239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Himmel verloren", description = "Ich brauche einen Gefallen, und Ihr seht aus wie jemand, der gerne Gefallen erledigt.\n\nEine alte Freundin von mir, Harleen Hohnzirper, sollte mich vor ein paar Tagen in der Stadt treffen. Wir wollten uns durch das Rubinfestmahl probieren, zum Frisör gehen und dann dieses schicke Auktionshaus besuchen, das es dort gibt.\n\nAber sie ist nicht gekommen. Sie verliert sich oft in ihrer Arbeit, aber ich würde mich besser fühlen, wenn ich wüsste, wo sie ist.\n\nVersucht es in den Bergen südlich von hier. Sie hat erwähnt, dass sie einen Abstecher dorthin machen will.", sourceObjective = "Findet Harleen Hohnzirper an den Blaufederklippen.", completion = "Die alte Knisterkurbel macht sich Sorgen, wie? Ich muss ihr wohl eine Runde ausgeben, wenn ich hier fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[71241] = { id = 71241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Enten auf Jagd", description = "Das Urzeitliche Tal ist erfüllt von der Magie der alten Drachen. Eine dort lebende Slyvernart wird bei meinem Volk für ihr Fell geschätzt, aber sie ist scheu und schwer zu finden.\n\nAnstatt zu versuchen, sie aufzuspüren, könnt Ihr nach unseren Jagdfallen in der Gegend suchen. Nehmt Fleisch der hiesigen Wasservögel, um sie neu zu stellen. Ich werde dann einige Klanmitglieder aussenden, um den Fang einzusammeln.", sourceObjective = "Stellt die Fallen des Klans Aylaag im Urzeitlichen Tal neu.", completion = "Vielen Dank. Unser Klan wird die Felle hoffentlich gut verkaufen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[71242] = { id = 71242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Sturmforscher", description = "Das sieht aus wie ein Bündel überschwellender Kraft von Kreaturen im Sturm der Primalisten.\n\nIn Valdrakken gibt es sicher einen Forscher, der sich dafür interessiert.", sourceObjective = "Bringt das Bündel an Elementarüberfluss zu einem Forscher in Valdrakken.\n\nBereitgestellter Gegenstand:", completion = "Oh, wunderbar! Das ist genau, wonach wir gesucht haben, danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[72008] = { id = 72008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Berg besiegen: Krolkoth" }
