quests[72039] = { id = 72039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Eure Taten sind essentiell für den Erfolg unserer Expedition auf den Dracheninseln. Deswegen wurde ich autorisiert, Euch diesen Vorratsanteil zur Unterstützung zuzuteilen. Weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[72040] = { id = 72040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Willkommen zurück, Abenteurer. So wie es aussieht, wurde Euer Vorratskontingent erhöht. Gut für Euch! Ihr habt es sicherlich verdient. Ich weiß, dass ich es Euch bereits gesagt habe, aber wir schätzen Eure Hilfe und sind schon gespannt, was Ihr als Nächstes tun werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[72041] = { id = 72041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Willkommen zurück, Abenteurer. Ich freue mich, dass ich autorisiert bin, Euren Vorratsanteil zu vergrößern, denn verdient habt Ihr ihn auf jeden Fall. Ich weiß, das sage ich jedes Mal, aber ich hoffe, Ihr setzt Eure Unterstützung unserer Bemühungen fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[72042] = { id = 72042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Willkommen zurück, Abenteurer. Ich freue mich, dass ich autorisiert bin, Euren Vorratsanteil zu vergrößern, denn verdient habt Ihr ihn auf jeden Fall. Ich weiß, das sage ich jedes Mal, aber ich hoffe, Ihr setzt Eure Unterstützung unserer Bemühungen fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[72043] = { id = 72043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Willkommen zurück, Abenteurer. Ich freue mich, dass ich autorisiert bin, Euren Vorratsanteil zu vergrößern, denn verdient habt Ihr ihn auf jeden Fall. Ich weiß, das sage ich jedes Mal, aber ich hoffe, Ihr setzt Eure Unterstützung unserer Bemühungen fort.", sourceObjectiveStatus = "unverified-source-field" }
