quests[72058] = { id = 72058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist der Huf erst ruiniert: Tarolekk" }
quests[72060] = { id = 72060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderbehandlung", description = "<Die Schlammmaske scheint gespannt hinsichtlich Eurer Pläne, ist aber auf diesem Ast in die Enge getrieben.>", sourceObjective = "Bringt die Sonnenbrille zu Zeldis zurück. Noch einmal.", progress = "Ich weiß, dass meine Sonnenbrille umwerfend ist, aber alles, was recht ist. Das ist nun das zweite Mal, dass ein Schlamm damit abgehauen ist.\n\nWie soll ich unter diesen Bedingungen atemberaubend sein?\n\nMoment, habt Ihr sie etwa noch einmal wiedergefunden?", completion = "Oh, wow. Seht Euch den ganzen Schnodder daran an.\n\n<Zeldis hält inne.>\n\nWisst Ihr, ich denke, dass sie sowieso aus der Mode gekommen ist.\n\nHaltet diesen Schlamm von mir fern.\n\nOder behaltet ihn als Haustier, was immer Euch glücklich macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[72061] = { id = 72061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmruferin Veldra" }
quests[72063] = { id = 72063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt Yennus Spielzeugboot zurück", description = "<Dieses handgefertigte Spielzeugboot ähnelt den Schiffen der Tuskarr. Yennu, das Tuskarrkind, hatte von einem Boot gesprochen, es muss ihm gehören.>", sourceObjective = "Bringt das Spielzeugboot zu Yennu beim Fluss auf den Ebenen von Ohn'ahra zurück.", completion = "Mein Boot! Mein Boot! Vielen lieben Dank! Ich werde es nie wieder aus den Augen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72067] = { id = 72067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Entspannung!", description = "Ihr da!\n\nIhr seht erschöpft aus. Verbraucht. Als bräuchtet Ihr dringend etwas Ruhe und Erholung. Da habe ich genau das Richtige! Das Bad der Ruhigen Träume ist der Ort, den Ihr sucht!\n\nGenießt unsere neuen Yougakurse, die sind GROSSARTIG. Oder vielleicht habt Ihr eher Lust auf eine Schlammmaske als Gesichtsbehandlung? Ich empfehle beides.\n\nDas Bad liegt gleich nördlich der Stadt!", sourceObjective = "Geht zum Bad der Ruhigen Träume.", completion = "Wie herrlich! Ich bin froh, dass Ihr uns besucht! Aber wir könnten wirklich Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72068] = { id = 72068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für das Abkommen: Ein Festmahl für alle", description = "Unsere Verbündeten benötigen Hilfe, {name}!\n\nEure Bemühungen auf den Inseln sind nicht unbemerkt geblieben. Unsere Vertrauten im Süden, die Tuskarr von Iskaara, möchten Eure Errungenschaften mit einem unübertroffenen Festmahl feiern!\n\nReist in das Land von Iskaara, während Ihr Eure Arbeit an der Seite der Mitglieder des Abkommens fortführt. Wenn Ihr die schimmernden Gewässer der Südlande erreicht, zögert nicht, Euch den Festlichkeiten anzuschließen!", sourceObjective = "Reist nach Iskaara im Azurblauen Gebirge und nehmt an einem gemeinschaftlichen Festmahl teil. Führt Eure Bemühungen, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen, fort.", completion = "Ihr seht weitgereist aus, {name}... und gut genährt. Eure abenteuerlichen Mühen stabilisieren unser Land und beruhigen unsere Verbündete.", sourceObjectiveStatus = "unverified-source-field" }
quests[72069] = { id = 72069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gletschernachschub", description = "Die Fische könnten besser beißen, findet Ihr nicht?\n\nWisst Ihr was, da kommt mir eine Idee. Wie es scheint haben wir fast alle Fische unter dem Eis gefangen. Könntet Ihr flussabwärts am Baumzahnpfad welche angeln, herbringen und in ein Eisloch werfen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und werft sie in ein Eisloch.", progress = "Habt Ihr die Fische bereits abgeworfen?", completion = "Gute Arbeit, ich kann schon wieder mehr Fische unter dem Eis funkeln sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72071] = { id = 72071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde zwei, angelt!", description = "Was haltet Ihr von ein wenig Angeln, {name}?\n\nGleich vor der Küste gibt es einen Schwarm Köderfische, der immer von dieser dummen Bestie angegriffen wird, sobald sie sich versammeln... Sie vergisst einfach, dass sie längst tot ist.\n\nSchwimmt raus und wedelt mit dem Köder, tut vielleicht, als wärt ihr eine verwundete Robbe, dann kann die Bestie nicht widerstehen.", sourceObjective = "Tötet Mochoby.", progress = "Er ist da draußen, ich kann es spüren.", completion = "Wer hat gewonnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72072] = { id = 72072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenquellensturz", description = "Die Fische könnten etwas besser beißen, meint Ihr nicht?\n\nDa kommt mir eine Idee. Der Legende nach waren diese Seen und Flüsse nicht immer voller Fische. Angeblich wurden diese Wasserlöcher mit Fischen bestückt, als die Drachen darüber segelten und sie fallen ließen! Könnt Ihr das glauben?\n\nVielleicht könntet Ihr es mit Eurem Drachen mal versuchen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und besteigt Euren Drachen, um sie von oben abzuwerfen.", progress = "Habt Ihr die Fische bereits abgeworfen?", completion = "Ha! Die Legenden sind wahr, fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72074] = { id = 72074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochlandhabitat", description = "Die Fische könnten etwas besser beißen, meint Ihr nicht?\n\nDa kommt mir eine Idee. Der Legende nach waren diese Seen und Flüsse nicht immer voller Fische. Angeblich wurden diese Wasserlöcher mit Fischen bestückt, als die Drachen darüber segelten und sie fallen ließen! Könnt Ihr das glauben?\n\nVielleicht könntet Ihr es mit Eurem Drachen mal versuchen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und besteigt Euren Drachen, um sie von oben abzuwerfen.", progress = "Habt Ihr die Fische bereits abgeworfen?", completion = "Ha! Die Legenden sind wahr, fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72075] = { id = 72075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißes Lager", description = "Die Fische könnten etwas besser beißen, meint Ihr nicht?\n\nDa kommt mir eine Idee. Der Legende nach sind diese Lavaseen nicht immer voller hitzeliebender Fische. Angeblich wurden diese Becken mit Fischen bestückt, als die Drachen darüber segelten und sie fallen ließen! Könnt Ihr das glauben?\n\nVielleicht könntet Ihr es mit Eurem Drachen mal versuchen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und besteigt Euren Drachen, um sie von oben abzuwerfen.", progress = "Habt Ihr die Fische bereits gesammelt?", completion = "Ha! Die Legenden sind wahr, fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72079] = { id = 72079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliches Festmahl" }
quests[72083] = { id = 72083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Glücksköder", description = "Ihr sucht mich in einer schweren Zeit auf, {race}, und nicht, weil ich tot bin.\n\nIch bin auf der Jagd gestorben, um sicherzugehen, dass die Bestie, die meine Mannschaft getötet hat, nie wieder töten kann.\n\nNein, das Problem ist, dass der Kampf unentschieden ausging!\n\nDer Geist der Bestie ist immer noch da draußen, so sicher ich hier vor Euch stehe. Aber als Geist kann ich nicht einmal meinen Glücksköder von den Aasfressern zurückholen, die meine Knochen abgenagt haben, um es nochmal zu versuchen!\n\nWürdet Ihr mir helfen?", sourceObjective = "Findet Kapitän Haabs Glücksköder.", progress = "Nein, ich weiß nicht, welcher ihn gefressen hat. Ich war zu der Zeit damit beschäftigt, tot zu sein.", completion = "Kein Fisch kann meinem Glücksköder widerstehen, lebendig oder tot!", sourceObjectiveStatus = "unverified-source-field" }
quests[72089] = { id = 72089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Himmelhochobservatorium", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72090] = { id = 72090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primalistenpläne stören" }
quests[72113] = { id = 72113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestalten hinter dem Schleier", sourceObjective = "Grüße, mein Freund.\n\nIhr habt viel Eurer Zeit hier unserer Hilfe gewidmet, aber ich kann spüren, dass Euer Schicksal Euch an einen anderen Ort ruft.\n\nIm Namen der vielen Seelen, die Ihr auf Eurer Reise gerettet habt, und als Licht der Führung für alle, denen Ihr noch begegnen werdet, möchte ich Euch dieses Geschenk überreichen. Möge es Euch daran erinnern, welche Wunder das Leben offenbart, wenn man nur ein wenig nachhilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[72114] = { id = 72114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acrosoth" }
quests[72116] = { id = 72116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liskron der Blendende" }
quests[72117] = { id = 72117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultureller Austausch", sourceObjective = "Fremdling, Ihr macht Euch langsam wirklich nützlich. Nehmt das, um Euch in kalten Nächten zu wärmen. Und dann erinnert Euch immer daran, dass wir Freunde sind.\n\n<Huseng grinst.>\n\nIch weiß, dass Ihr großartige Taten für unser Volk vollbringt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72121] = { id = 72121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Große Panzerkhan" }
quests[72122] = { id = 72122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehemalige Ökologen", description = "Die Verwundeten sind stabilisiert, aber meine Sorgen sind noch nicht vorüber, {name}.\n\nZwei Drachenbrutökologen sind zum Außenposten gekommen, um das Sumpfland zu untersuchen. Seit dem Angriff hab ich keine einzige Schuppe von ihnen erblickt und das bereitet mir Sorgen.\n\nKönntet Ihr Euch nach ihnen umsehen und ihnen helfen, wenn Ihr hinauszieht?\n\nUnd passt dabei auf. Angeblich lauern im Sumpf Gorlocs.", sourceObjective = "Sucht nach den verschollenen Ökologen.", completion = "Ein Angriff? Am Drachenherzaußenposten?\n\nDas klingt nicht gut. Aber wie Ihr sehen könnt, habe ich hier meine eigene Krise.", sourceObjectiveStatus = "unverified-source-field" }
quests[72126] = { id = 72126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlabbro, die unglaubliche Schnecke" }
quests[72127] = { id = 72127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Lancer" }
quests[72128] = { id = 72128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enkine der Gefräßige" }
quests[72129] = { id = 72129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar zur Hilfe", description = "Willkommen in Dalaran, {name}. Ich bin froh, dass Ihr es geschafft habt.\n\nTrefft mich in der Violetten Zitadelle, es gibt viel zu tun.", sourceObjective = "Trefft Khadgar in der Violetten Zitadelle in Dalaran.", completion = "Schön, Euch wiederzusehen, {name}.\n\nDie Verheerten Inseln brauchen dringend Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72130] = { id = 72130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessener Greif" }
quests[72131] = { id = 72131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbestand", sourceObjective = "Grüße, Drachenreiter. Ich habe gerade mein Vorratslager überprüft und die Fülle bewundert. \n\nEinen Teil dieses bescheidenen Reichtums haben wir Euch zu verdanken. Es ist nur gerecht, dass ich Euch einen Anteil davon anbiete.\n\nAber verratet es niemandem. Ich habe einen Ruf zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72134] = { id = 72134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuerassistenz", description = "Wir haben herausgefunden, dass es auf den Verheerten Inseln, das Land, über dem wir schweben, viele Probleme gibt. \n\nWir werden von hier aus tun, was wir können. Ich möchte Euch bitten, auf der nahegelegenen Karte nachzusehen, wem Ihr als erstes helfen könnt.", sourceObjective = "Verwendet die Späherkarte, um Eure erste Zone auszuwählen.", completion = "Gute Wahl, Abenteurer. Fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[72135] = { id = 72135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharus: Verborgenes Wissen", description = "Wir haben ein Problem, <Reisender/Reisende>. Zuerst erschienen die Djaradin innerhalb von Neltharus, also werden sie dessen Hallen plündern!\n\nNeltharus enthält viele Schätze, aber vor allem viel Wissen. Die Geschichte unseres Schwarms, dessen Fall... Sabellian und Furorion suchen nach Informationen über Neltharions Leben und seine Bestrebungen.\n\nVersucht, möglichst viel davon zu finden, bevor die Djaradin alles mitnehmen!", sourceObjective = "Findet 12 von Neltharions Notizen, 3 Obsidiantagebücher und einen Forschungsfolianten in Neltharus.", progress = "Habt Ihr irgendwelche Gegenstände entdeckt?", completion = "Diese Gegenstände sind wundervoll! Voller Informationen, die ich genauer studieren muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[72137] = { id = 72137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kükenpläne", sourceObjective = "Mein Freund, schafft mir dieses Ding aus den Augen. Kauft es mir ab. Bitte. Sie nennen es einen \"Hufhelfer\", aber es geht mir nur auf die Nerven. Es ist immer im Weg und auch noch nicht groß genug, um wirklich nützlich zu sein. Ich will es loswerden.\n\nWas? Nein, ich kann es Euch nicht einfach schenken. Meine Frau würde mir nie verzeihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72154] = { id = 72154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skag der Werfer" }
quests[72155] = { id = 72155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitung der Verzauberung", description = "Die Akademie von Algeth'ar hat eine Bestellung von Verzauberungsruten aufgegeben. Wir brauchen alle Unterstützung, die wir haben können, wenn wir die Bestellung rechtzeitig erfüllen wollen. Könntet Ihr uns helfen?", sourceObjective = "Stellt 2 runenverzierte Drakoniumruten für Soragosa in Valdrakken her.", progress = "Beeilt Euch! Uns läuft die Zeit davon!", completion = "Vielen Dank. Mit der Lieferung dieser Bestellung wird die Akademie im Nu neue Verzauberer ausbilden!\n\nHier, studiert das. Auch für einen fähigen Verzauberer gibt es immer Neues zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72156] = { id = 72156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuriger Flug", description = "Die Schmiede kühlt ab! Schnell, könnt Ihr mir helfen? Bringt mir etwas tobendes Feuer, vielleicht hilft das!", sourceObjective = "Sammelt 15 tobendes Feuer für Sekita den Wühler in Valdrakken.", progress = "Die Schmiede ist beinahe erloschen! Habt Ihr es?", completion = "Ja, ja!\n\nDas sollte genügen.\n\nNehmt meine Feldnotizen, bevor Ihr geht. Darin findet Ihr bestimmt etwas, das Euch mehr über Bergbau beibringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72157] = { id = 72157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gewicht der Erde", description = "Ich habe eine Bestellung über mehrere hundert Tonnen urzeitliche geschmolzene Legierung erhalten, aber ich habe keine tobende Erde mehr! Ich weiß, ich verlange viel von Euch, aber es wird sich lohnen!", sourceObjective = "Sammelt 15 tobende Erde für Sekita den Wühler in Valdrakken.", progress = "Die Kunden sitzen mir im Nacken. Habt Ihr sie?", completion = "Perfekt, das ist genau, was ich brauche.\n\nNehmt diese alten Feldnotizen. Darin findet Ihr bestimmt etwas, das Euch mehr über Bergbau beibringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72158] = { id = 72158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dichte Lieferung", description = "Unsere Schuppen sind hart, aber wir können immer noch zusätzlichen Schutz gebrauchen. Für unsere Rüstungen sind nur die dichtesten Bälge geeignet. Die sind nicht einfach zu beschaffen, aber vielleicht seid Ihr dieser Herausforderung ja gewachsen?\n\nIch habe gesehen, was Ihr könnt. Geht einige Bälge für unser Lager beschaffen.", sourceObjective = "Sammelt 2 dichte Bälge für Ralathor den Zerfurchten in Valdrakken.", progress = "Für unser Handwerk ist das Beste gerade gut genug.", completion = "Ah, die sind von hervorragender Qualität. Ich hatte Euch nicht falsch eingeschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72159] = { id = 72159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Schuppen für die Augen", description = "Schuppen haben vielerlei Verwendungszwecke. Sie bieten Schutz, in einigen Fällen aber auch eine glatte, reflektierende Oberfläche. Viele unserer besten Spiegel sind eigentlich Schuppen.\n\nGenau diese Spiegel werden zufälligerweise auch stark nachgefragt. Besorgt mir einige schimmernde Schuppenbälge, dann teile ich ein paar Geheimnisse meiner Kunst mit Euch.", sourceObjective = "Sammelt 2 schimmernde Schuppenbälge für Ralathor den Zerfurchten in Valdrakken.", progress = "Konntet Ihr Bälge beschaffen?", completion = "Ah, Ihr habt da genau das Richtige. Ihr beeindruckt mich immer wieder.\n\nIhr könnt diese Notizen haben, wie versprochen. Daraus könnt Ihr sicher noch etwas lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72166] = { id = 72166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Schlacht beweisen", description = "Wenn Ihr Sterblichen es so sehr liebt, um jedes Land zu streiten, das Ihr findet, dann bitte.\n\nWenigstens wird es amüsant. Für mich zumindest. Dann lasst uns doch einmal sehen, wie gut Ihr Euch \"beweisen\" könnt.", sourceObjective = "Verdient Ehre auf zufälligen Schlachtfeldern.", completion = "Ihr war erfolgreich. Das war zu erwarten, es war eine einfache Schlacht. Hier, nehmt diese Belohnungen, sie werden Euch helfen, solltet Ihr je in eine echte Schlacht geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72167] = { id = 72167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg beweisen", description = "Ihr wollt also eine \"echte Herausforderung\"? So sei es. Ich kenne einige große Konflikte, die sogar für mich eine Herausforderung darstellen könnten.\n\nIch bin neugierig, wie schnell Ihr scheitert... ich meine gewinnt. Wollen wir sehen, ob Ihr Euch mir gegenüber beweisen könnt.", sourceObjective = "Verdient Ehre auf epischen Schlachtfeldern.", completion = "Also gut. Ich schätze, ich muss meine Einschätzung Euch gegenüber ändern und beeindruckt sein. Nur ein wenig. Hier, das habt Ihr Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[72168] = { id = 72168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Geplänkeln beweisen", description = "Ihr habt Vertrauen in Eure taktischen Fähigkeiten, wie? Mir ist zu Ohren gekommen, dass es oft kleinere Geplänkel unter Euch Sterblichen gibt. Sucht Euch einige Gegner, gegen die Ihr antreten könnt.\n\nBeweist Euch, dann kehrt zu mir zurück.", sourceObjective = "Verdient Ehre in Arenageplänkeln.", completion = "Das scheint recht gut gelaufen zu sein. Ihr könnt das hier haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72169] = { id = 72169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Arenen beweisen", description = "Ihr liebt Auseinandersetzungen wirklich, oder? Da habe ich gute Neuigkeiten für Euch: Das haben wir gemeinsam. Krieger und Kriegerinnen wie Ihr treffen in vorbestimmten Gegenden aufeinander, um zu kämpfen. Nehmt teil, und wenn Ihr gewinnt, bekommt Ihr eine Belohnung.\n\nBeweist Euch, dann kehrt zu mir zurück.", sourceObjective = "Verdient als Gruppe Ehre auf gewerteten Schlachtfeldern.", completion = "Ihr habt erreicht, weswegen Ihr ausgezogen seid, also halte ich meinen Teil unseres Handels ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72170] = { id = 72170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Zusammenarbeit beweisen", description = "Ich finde es spannend, wie viele Sterbliche wie Ihr im Kampf aufblühen. Ich habe mir sagen lassen, dass andere wie Ihr in vorbestimmten Teams gegeneinander antreten. Sucht Euch weitere Sterbliche, mit denen Ihr Euch dieser Herausforderung stellen könnt.\n\nBeweist Euch, dann kehrt zu mir zurück.", sourceObjective = "Verdient Ehre auf gewerteten Schlachtfeldern.", completion = "Ich bin überrascht, wie erfolgreich Ihr bei dieser Aufgabe wart. Ich schätze, das habt Ihr Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[72171] = { id = 72171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Einzel beweisen", description = "Euer Eifer, selbst den Konflikt zu suchen, gefällt mir. Wenn Ihr so sehr auf Eure Fähigkeiten vertraut, dann werde ich hierbleiben und zusehen. Zur Belustigung.\n\nBeweist Euch, dann kehrt zu mir zurück.", sourceObjective = "Schließt 12 Runden im gemischten Einzel ab.", completion = "Euer Training scheint sich langsam auszuzahlen. Das könnt Ihr haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72172] = { id = 72172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz, Splitter, und chromatischer Staub", description = "Die Basiskomponenten scheinen bei uns immer knapp zu sein. Essenzen, Splitter... und unser Vorrat an chromatischem Staub ist beinahe aufgebraucht.\n\nWenn es Euch nichts ausmacht, uns mit dem Aufstocken zu helfen, halten wir vielleicht mehr als einen Tag durch, ohne die Vorräte auffüllen zu müssen.", sourceObjective = "Stellt 10 chromatischen Staub für Soragosa in Valdrakken her.", progress = "Uns ist der chromatische Staub schon ausgegangen! Habt Ihr welchen?", completion = "Habt Dank. Ich bin sicher, diesmal werden die Vorräte länger halten.\n\nHier, studiert das, wenn Ihr Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72173] = { id = 72173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberungen schienen nie gefragter zu sein", description = "Die Drachenschuppenexpedition hat einige Verzauberungen für ihre Ausrüstung bestellt.\n\nDie Dracheninseln können ein gefährlicher Ort sein. Ich kann verstehen, dass sie einige Armschienenverbesserungen brauchen.", sourceObjective = "Stellt 2 Schriftstücke des Lebensraubs für Soragosa in Valdrakken her.", progress = "Die Drachenschuppenexpedition wartet auf ihre Verzauberungen.", completion = "Ich werde die sofort der Drachenschuppenexpedition schicken.\n\nNehmt das, um Euer Wissen über Verzauberkunst zu erweitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[72175] = { id = 72175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine szeptakuläre Zeit", description = "Diese Woche sind einige aufregende Bestellungen reingekommen! Die Studenten der Akademie von Algeth'ar werden sich Kopf über Horn auf diese Szepter stürzen.\n\nWarum helft Ihr uns nicht mit der Herstellung einiger Szepter?", sourceObjective = "Stellt 3 Szepter des Spektakels: Feuer und 3 Szepter des Spektakels: Luft für Soragosa in Valdrakken her.", progress = "Die Studenten von Algeth'ar werden ungeduldig.", completion = "Wunderbar! Die Studenten werden sie lieben.\n\nNehmt das, um Euer Wissen über Verzauberkunst zu erweitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[72181] = { id = 72181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Normal Random - 1st" }
quests[72182] = { id = 72182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Normal Random - Nth" }
quests[72184] = { id = 72184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Raid Finder - 1st" }
quests[72185] = { id = 72185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Raid Finder - Nth" }
quests[72187] = { id = 72187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Heroic Random - 1st" }
quests[72188] = { id = 72188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - DF - Heroic Random - Nth" }
quests[72189] = { id = 72189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenvielfalt", description = "Gefällt Euch der Schmetterlingsgarten?\n\nWisst Ihr, südlich von hier gibt es einen noch viel größeren Garten. Ein alter Drakonid namens Gryrmpech kümmert sich darum.\n\nEr kann immer ein Paar helfende Hände brauchen. Er hat einen \"Assistenten\", aber ich habe ihn noch nie gesehen. Ich glaube nicht, dass er eine große Hilfe ist.\n\nWenn Ihr vorbeikommt, sagt ihm, dass Xina Euch geschickt hat.", sourceObjective = "Sprecht mit Gryrmpech.", completion = "Gelobt seien die Titanen, Hilfe, endlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[72190] = { id = 72190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reservoirreservierungen", description = "{class}! Ich kenne da jemanden, der dringend Eure Fähigkeiten benötigt.\n\nDas Tyrholdreservoir wurde von den Primalisten angegriffen. Ich konnte gerade noch entkommen, aber andere hatten weniger Glück.\n\nEs ist gleich nördlich von hier. Findet Zuttiki, sie kann Euch weitere Details nennen.\n\nDas heißt... wenn sie noch lebt.", sourceObjective = "Findet Zuttiki.", completion = "Talikka ist entkommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72191] = { id = 72191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[72192] = { id = 72192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Infusion: Entropie zu Ordnung", description = "Die Primalisten wollen das elementare Chaos in die Welt zurückbringen und machen vor nichts Halt, wenn es darum geht, ihr Ziel zu erreichen.\n\nIch habe üble Neuigkeiten erhalten, dass sie in die Hallen der Infusion unter Tyrhold eingedrungen sind. Sie versuchen, die Werke von Hüter Tyr für ihre eigenen niederträchtigen Zwecke zu missbrauchen.\n\nBitte, Ihr müsst die Bedrohung der Primalisten aus diesen heiligen Hallen vertreiben, {name}.", sourceObjective = "Betretet die Hallen der Infusion und besiegt den urtümlichen Tsunami.\n\nIhr könnt die Hallen der Infusion allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", progress = "Habt Ihr die Hallen von der Bedrohung der Primalisten befreit, {name}?", completion = "Die Hallen der Infusion sind einmal mehr sicher, dank Eurer Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72193] = { id = 72193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Akademie von Algeth'ar", description = "Mir ist zu Ohren gekommen, dass die Akademie von Algeth'ar sich wieder dem Rest der Welt geöffnet hat.\n\nVor langer Zeit waren ihre geheiligten Hallen nur für Drachen geöffnet, doch in den vergangenen Jahren wurde die Direktorin von der Weisheit ereilt, jeden willkommen zu heißen, der lernbegierig ist. Sie bat mich um Empfehlungen zu vielversprechenden Studenten.\n\nEs wäre mir eine Ehre, Euch, als <großartigen Verbündeten/großartige Verbündete> der Drachenheit, an unserer ebenso großartigen Akademie zu wissen. Es obliegt ganz allein Euch, dieses Angebot anzunehmen oder nicht, aber ich bin mir sicher, dass Doragosa Euch gerne wenigstens eine Führung über das Akademiegelände geben würde.", sourceObjective = "Lasst Euch durch das Gelände der Akademie von Algeth'ar führen.\n\nIhr könnt die Akademie von Algeth'ar allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", progress = "Ich hoffe, Ihr genießt Eure Zeit an der Akademie. Sie ist ein beeindruckender Ort.", completion = "Scheint, als hättet Ihr einen ereignisreichen ersten Tag gehabt. Gut, dass Ihr bereits daran gewöhnt seid, mit unerwarteten Situationen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72240] = { id = 72240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Obsidianwächter", description = "Die Begeisterung dieser Toddy ist bewundernswert. Ich hoffe nur, dass sie vor lauter Enthusiasmus nicht die Gefahren ignoriert, die uns auf den Dracheninseln erwarten.\n\nDennoch, die Obsidianwächter sind zum Schutze der Expedition verpflichtet.\n\nIch muss mit Furorion und dem Lordkommandanten über die Mission sprechen.\n\nDie anderen Dracthyr erkunden die Stadt. Sucht meinen treuen Leutnant Derwischian und gebt ihr Bescheid, dass wir uns an den Docks versammeln. Sie wird meine Befehle an den Rest der Truppe weitergeben.", sourceObjective = "Überbringt die Befehle des Schuppenkommandanten an Derwischian und die Obsidianwächter.", progress = "Ihr glaubt, ein Dracthyr kann schneller fliegen als ein Greif?", completion = "Ich freu mich riesig, dass die Dracthyr mit uns kommen.\n\nIch kann's kaum erwarten, diesen Schuppenkommandanten zu einem Rennen auf Wildfeder rauszufordern.\n\nGegen meinen Greifen haben die ollen Lederflappen keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[72241] = { id = 72241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen der Vergangenheit", description = "Ich bin Glutthal, eine Schuppenkommandantin der Dracthyr. Furorion half uns, nachdem wir aus unserer langen Stasis erwacht waren, und nun ist es an mir, ihm zu helfen.\n\nIhr habt zweifellos viele Fragen über mein Volk und unsere Geschichte. Bis vor Kurzem hatte ich das auch.\n\nAber Nozdormu der Zeitlose hat viele verlorene Wahrheiten über die Dracthyr aufgedeckt. Er hat mir eine Vision unserer Herkunft gezeigt... und warum wir weggesperrt wurden. \n\nLasst mich Euch von den Dingen erzählen, die ich gesehen habe.", sourceObjective = "Sprecht mit Schuppenkommandantin Glutthal.", progress = "Wir können viel voneinander lernen.", completion = "Nun kennt Ihr die Wahrheit.\n\nDoch Vergangenheit ist Vergangenheit. Es ist an der Zeit, dass die Dracthyr eine neue Zukunft an der Seite der Völker Azeroths beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72242] = { id = 72242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingenieurskunst der Dracheninseln", sourceObjective = "Hallöchen! Willkommen auf den Dracheninseln! Hey, Ihr seht aus, als hättet Ihr Freude an Explosionen. Darf ich Euch ein paar Geräte zeigen, an denen ich arbeite?\n\nIch kann Euch ein paar neue Ingenieurskunstbaupläne beibringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72243] = { id = 72243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde der Dracheninseln", sourceObjective = "Willkommen auf den Dracheninseln, mein Freund!\n\nDieses grüne Land ist so anders, so wunderschön. Als Kräuterkundiger wisst Ihr das natürlich bereits!\n\nWenn Ihr möchtet, kann ich Euch zeigen, wo die auf den Dracheninseln heimischen Kräuter zu finden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72244] = { id = 72244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inschriftenkunde der Dracheninseln", sourceObjective = "Guten Tag!\n\nIhr müsst der neue Schreiber sein. Lasst mich Euch zeigen, was ich von diesen drakonischen Glyphen bereits übersetzen konnte.\n\nIch kann Euch neue Inschriftenkundetechniken der Dracheninseln beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72245] = { id = 72245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemie der Dracheninseln", sourceObjective = "Willkommen auf den Dracheninseln! Ihr seht mir wie ein begabter Alchemist aus. Darf ich Euch erzählen, was ich über drakonische Techniken gelernt habe?\n\nIch kann Euch alles beibringen, was ich über Alchemie weiß. Dann könnt Ihr auch die Inseln erforschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72246] = { id = 72246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhige Träume", description = "Willkommen im Bad der Ruhigen Träume!\n\nIch muss mich entschuldigen, wir können wegen gewisser Umstände, die außerhalb unserer Kontrolle liegen, keine neuen Gäste aufnehmen!\n\nLasst mich Euch an Xijan Dornenpranke, den Badmanager, verweisen. Er ist qualifiziert, Euch alle Fragen zu beantworten.", sourceObjective = "Sprecht mit dem Badmanager.", completion = "Willkommen im Bad der Ruhigen Träume! Hier könnt Ihr an allen möglichen Aktivitäten zur Entspannung teilnehmen!\n\nOh! Ihr seid hier, um zu helfen? Es wäre mir eine Ehre, Eure Unterstützung anzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72247] = { id = 72247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelierskunst der Dracheninseln", sourceObjective = "He, Ihr da! Mögt Ihr glatte Sachen? Glänzende Sachen?\n\nSchaut Euch an. Natürlich tut Ihr das.\n\nIch kann Euch beibringen, wie Ihr die glattesten, glänzendsten Sachen überhaupt herstellt. Ihr müsst es nur sagen, ich kümmere mich um den Rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[72249] = { id = 72249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneiderei der Dracheninseln", sourceObjective = "<Zayn betrachtet Eure Kleidung mit einem strengen Blick.>\n\nLasst mich Euch ein paar Hinweise zur Schneiderei geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72250] = { id = 72250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst der Dracheninseln", sourceObjective = "<Chefkoch Stacks macht einige typische Kochgeräusche und -gesten. Seine Schneebesen wirbeln herum! Seine Feuerstellen lodern und zischen! Er schlägt so ernst auf seine Bratpfanne, als wäre sie ein großer Gong!\n\nDas gesamte Gasthaus applaudiert seiner Weisheit.\n\nNachdem Ihr seinem ausgeklügelten Auftritt zugesehen habt, seid Ihr auf wundersame Weise selbst besser im Kochen geworden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72251] = { id = 72251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst der Dracheninseln", sourceObjective = "<Chefkoch Stacks macht einige typische Kochgeräusche und -gesten. Seine Schneebesen wirbeln herum! Seine Feuerstellen lodern und zischen! Er schlägt so ernst auf seine Bratpfanne, als wäre sie ein großer Gong!\n\nDas gesamte Zelt applaudiert seiner Weisheit.\n\nNachdem Ihr seinem ausgeklügelten Auftritt zugesehen habt, seid Ihr auf wundersame Weise selbst besser im Kochen geworden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72252] = { id = 72252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln auf den Dracheninseln", sourceObjective = "Seid Ihr gekommen, um Euch an der Jagd zu beteiligen? Ähm, ich meine... am Fisch? An der Fischjagd?\n\n<Danielle lockert den Griff um ihre Angel und räuspert sich nervös.>\n\nIhr seht jedenfalls aus, als hättet Ihr Ahnung vom Fischen. Hier, ich zeige Euch, wie das Angeln auf diesen Inseln funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[72253] = { id = 72253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln auf den Dracheninseln", sourceObjective = "Beim Fischen geht es darum, das Wasser unter Euch zu spüren. Irgendwann verwandelt sich das Wasser in den Himmel und der Himmel in das Wasser und Ihr schwebt in den Wolken wie ein Flugdrachen! Und Eure Angelrute ist die Drachenschnur!\n\n...oder vielleicht sind das auch nur die vulkanischen Dämpfe. Aber so oder so ist Angeln sehr entspannend. Ich würde mich freuen, Euch die Angelkunst beizubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72254] = { id = 72254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angler Tinnaks Geist" }
quests[72256] = { id = 72256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelkrallen", description = "Naleidea scheint voller Begeisterung, aber sie ist Historikerin, keine Soldatin. Sie hat keine Ahnung von den Gefahren, denen wir uns auf den Dracheninseln gegenübersehen werden.\n\nNicht, dass irgendjemand sich Sorgen machen müsste. Schließlich werden die Dunkelkrallen die Expedition schützen.\n\nIch werde mit Ebyssian und den Anführern Eurer Horde die Missionslogistik besprechen.\n\nMein Leutnant Kodethi erkundet mit den anderen Dracthyr die Stadt. Seid so gut und gebt ihm Bescheid, dass wir uns am Zeppelinturm versammeln. Er wird meine Befehle an die anderen weitergeben.", sourceObjective = "Überbringt die Befehle der Schuppenkommandantin an Kodethi und die Dunkelkrallen.", progress = "Glaubt Ihr, ein Dracthyr wäre über die gesamte Strecke hin zu den Dracheninseln schneller als ein Schiff? Irgendwann würde sicher die Erschöpfung ihren Tribut fordern, oder nicht?", completion = "Ich bin höchst erfreut, dass die Dracthyr uns auf der Expedition begleiten.\n\nIhre einzigartige Perspektive wird sich gewiss als wertvoll erweisen. Und wenn sie mehr über ihre Geschichte in Erfahrung bringen, gelingt es ihnen womöglich besser, mit den aktuellen Umständen zurechtzukommen.\n\nWie ich schon sagte, die Geschichte hat noch jede Wunde geheilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72259] = { id = 72259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbeartefakte", progress = "Habt Ihr noch ein Artefakt gefunden?", completion = "Wenn Ihr mir mehr Artefakte bringt, wächst unser Wissen über die Inkarnationen und ihr Zeitalter.\n\nIch muss Euch danken. Als Mitglied der Drachenschuppenexpedition möchte ich betonen, wie wichtig Euer Beitrag ist. Und als Forscher möchte ich Euch für den Reichtum an Erkenntnissen danken, die ich aus den Artefakten gewinnen konnte. Damit habt Ihr mir einen lange gehegten Traum erfüllt.\n\nBitte, nehmt diese Vorräte und setzt sie weise ein." }
quests[72260] = { id = 72260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbeartefakte", progress = "Habt Ihr weitere Artefakte gefunden?", completion = "Vielen Dank für Euren großzügigen Beitrag an Artefakten.\n\nUnser Studium der Inkarnationen verläuft dank Eurer Hingabe, die Artefakte zu finden und zu spenden, erfolgreich. Eure Unterstützung ist in der Drachenschuppenexpedition sehr willkommen.\n\nBitte, nehmt mehr Vorräte von uns!" }
quests[72261] = { id = 72261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als ein Gefängnis?", description = "<Das uralte Artefakt sieht elementar aus. Lillian Mondenschein in Valdrakken kann Euch vielleicht mehr sagen.>", sourceObjective = "Bringt das uralte Gewölbeartefakt zu Lillian Mondenschein.", progress = "Habt Ihr mir etwas zum Untersuchen mitgebracht?", completion = "Die Inkarnationen wurden im Gewölbe eingesperrt, aber abgesehen davon wissen wir sehr wenig über sie oder ihr Gefängnis.\n\nArtefakte wie dieses können etwas Licht auf ihre Kultur, ihre Geschichte und... ihre Macht werfen. Sie zu studieren könnte unsere Chancen im Kampf gegen die Primalisten erhöhen. Bringt mir mehr davon und ich werde Euch mit Vorräten belohnen.\n\nOh, und ich werde eine Notiz für Katalogisiererin Jakes anfügen, die sie an Eure anhaltende Unterstützung für die Drachenschuppenexpedition erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[72263] = { id = 72263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavallerie vor", description = "<Rufer/Ruferin>! Hier gibt es noch immer Vorquinherden!\n\nIch habe ein paar der Tiere zusammengetrieben, die als Reittiere dienen könnten, wenn Eure Schwingen müde werden. Wisst Ihr noch, wie man reitet?\n\nDieses Exemplar wird Euch zugeteilt, schließlich scheuchen Euch die Schuppenkommandanten ziemlich viel herum. Bitte kümmert Euch gut darum.", sourceObjective = "Lernt, Euer persönliches Vorquinreittier zu reiten.", completion = "{class}, hier gibt es noch immer Vorquinherden!\n\nIch habe ein paar der weniger sturen Exemplare zusammengetrieben, die als Reittiere dienen könnten, wenn Eure Schwingen müde werden. Wisst Ihr noch, wie man reitet?\n\nMir wurde aufgetragen, Euch eines zuzuteilen, schließlich scheuchen Euch die Schuppenkommandanten ziemlich viel herum. Bitte kümmert Euch gut darum.", sourceObjectiveStatus = "unverified-source-field" }
quests[72266] = { id = 72266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küste des Erwachens", description = "Die Drakonide Sendrax sucht Hilfe für die Unterstützung der Neuankömmlinge an der Küste des Erwachens.", sourceObjective = "Trefft Sendrax an der Küste des Erwachens.", completion = "Oh, hallo! Ich habe eine tolle Idee, wie Ihr uns gerade aushelfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72267] = { id = 72267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebenen von Ohn'ahra", description = "Der grüne Drachenschwarm braucht die Hilfe von Abenteurern. Doch Ihr müsst Euch erst mit den Zentauren der Ebenen verbünden.\n\nBotschafter Taurasza kann Euch helfen.", sourceObjective = "Trefft Botschafter Taurasza im Außenposten der Rubinschuppen.", completion = "Wir beide haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72268] = { id = 72268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurblaues Gebirge", description = "Die Kirin Tor brauchen alle Hilfe, die sie bekommen können, wenn es darum geht, den Schwurstein der blauen Drachen aufzuspüren.\n\nEinige ihrer Magier wurden hilfesuchend auf den Ebenen von Ohn'ahra gesehen.", sourceObjective = "Sprecht mit Masud dem Weisen auf den Ebenen von Ohn'ahra.", completion = "Ah, noch ein Abenteurer! Wir könnten Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72269] = { id = 72269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thaldraszus", description = "Alexstrasza die Lebensbinderin plant ein Treffen am Sitz der Aspekte, um über die Bedrohung durch die Primalisten zu sprechen.\n\nSie hat alle hilfsbereiten Abenteurer eingeladen.", sourceObjective = "Reist nach Valdrakken und trefft Euch mit Alexstrasza der Lebensbinderin.", completion = "Willkommen in Valdrakken, {name}. Fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[72279] = { id = 72279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Grüße, Abenteurer. Bitte, nehmt diese Vorräte, die Euch bei der Unterstützung unserer Gemeinschaft helfen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72280] = { id = 72280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Willkommen, {race}. Ich habe mehr Vorräte für Euch, als Dank für Eure weitere Unterstützung unserer Gemeinschaft. Eure Schritte und Beute mögen sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72281] = { id = 72281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Ah, unsere Wege kreuzen sich erneut, {name}. Ich bin froh, dass Ihr sicher zu uns zurückgekehrt seid. Eure Taten haben Euch in Iskaara Ehre eingebracht. Bitte, nehmt diese Vorräte zum Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[72282] = { id = 72282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72283] = { id = 72283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Eure Siege gegen die Primalisten haben das Interesse des Abkommens erweckt, {class}. Sie haben beschlossen, Euch großzügig zu entlohnen... in der Hoffnung, dass Ihr weiterhin für unsere Sache kämpft, natürlich.\n\nNehmt diesen größeren Anteil an Vorräten. Nutzt sie, um die Dracheninseln zu verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72284] = { id = 72284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte" }
quests[72291] = { id = 72291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichte eines denkwürdigen Sieges", description = "Das war ein guter Kampf! \n\nÄlteste Poa in Iskaara wird an der Geschichte dieses Sieges interessiert sein.", sourceObjective = "Erzählt der Ältesten Poa in Iskaara von Eurem Sieg.", progress = "Jedem können die spannendsten Geschichten passieren. \n\nUnsere Taten machen uns zu dem, was wir sind, und ich suche immer nach den beeindruckendsten Taten, um sie zu einer Inspiration für andere zu machen.", completion = "Was höre ich da? Ihr habt eine Geschichte für mich? Setzt Euch, lasst hören!\n\n<Älteste Poa lauscht Eurer Geschichte von Eurem Sieg über einen sonderbaren Gegner.>\n\nDas war spannend! Habt Dank, dass Ihr das mit mir geteilt habt, Jungspund.", sourceObjectiveStatus = "unverified-source-field" }
quests[72292] = { id = 72292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichte eines spektakulären Sieges", description = "Das war ein majestätischer Kampf!\n\nÄlteste Poa in Iskaara wird an der Geschichte dieses beeindruckenden Sieges interessiert sein.", sourceObjective = "Erzählt der Ältesten Poa in Iskaara von Eurem Sieg.", progress = "Jedem können die spannendsten Geschichten passieren. Besonders, wenn man furchtlos in den Bau des Feindes eindringt...\n\nUnsere Taten machen uns zu dem, was wir sind, und ich suche immer nach den beeindruckendsten Taten, um sie zu einer Inspiration für andere zu machen.", completion = "Oh, Ihr habt eine Geschichte für mich? Setzt Euch, lasst hören.\n\n<Älteste Poa lauscht Eurer Geschichte von Eurem Sieg über einen sonderbaren Gegner.>\n\nDas war spannend! Habt Dank, dass Ihr das mit mir geteilt habt, junger Freund. Ich werde diese Geschichte nicht vergessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72293] = { id = 72293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuer auf den Dracheninseln", description = "Oh, ich weiß, was ich tun kann!\n\nDie Drachenschuppenexpedition hat eine schöne Karte der Dracheninseln in der Nähe aufgehängt.\n\nIhre Zeichnungen sind sehr genau und detailliert, wie ich finde. Verzeiht, Ihr wollt keine Kunstanalyse hören.\n\nIhr solltet Euch die Karte ansehen, um herauszufinden, welche Gegenden auf den Dracheninseln Eure Hilfe brauchen können!", sourceObjective = "Betrachtet die Späherkarte, um eine Gegend auf den Dracheninseln auszusuchen, die Ihr unterstützen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72294] = { id = 72294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Lok'tar, Abenteurer. Ihr müsst der neue Inschriftenkundige sein, der für die Expedition aushilft! Ich soll Euch dieses Notizbuch geben. Unsere Schreiber haben die Stifte zusammengesteckt, um Euch ein paar Notizen zusammenzustellen, die Euch den Einstieg in das Handwerk der Dracheninseln erleichtern sollen. Kommt zu mir zurück, wenn Ihr sie gelesen habt. Vielleicht habe ich dann mehr für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[72295] = { id = 72295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Da ist ja mein liebster Inschriftenkundiger! Alle reden über die großartige Qualität Eurer Inschriften, {name}. Als Belohnung habe ich die Inschriftenmeister gebeten, Euch mehr Anweisungen und Übungen zusammenzustellen, die Euch helfen können, Euer Handwerk zu meistern. Ich bin stolz auf Euch, {class}. Und jetzt geht wieder an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[72296] = { id = 72296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Wissens", sourceObjective = "Ah, Drachenreiter! Ich weiß, dass Ihr ein fähiger Lederverarbeiter seid, aber wir Maruuk haben eigene Methoden, die Euch nützlich sein könnten. \n\nUnsere Lederverarbeiter haben diese Notizen zusammengestellt, um Euren Fortschritt zu unterstützen. Vielleicht stattet Ihr ihnen einen Besuch ab und teilt Eure Kenntnisse ebenfalls mit ihnen.\n\nUnter Freunden kennt der Himmel keine Geheimnisse!", sourceObjectiveStatus = "unverified-source-field" }
quests[72297] = { id = 72297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Geheimnissen", sourceObjective = "{name}, Ihr habt das Herz eines Zentauren... und Ihr habt größere Hingabe für Euer Handwerk bewiesen, als wie je erwartet hätten. \n\nDas letzte Mal, als wir uns über Lederverarbeitung unterhalten haben, habe ich eine erste Portion des Wissens unserer Meisterhandwerker mit Euch geteilt. Aber Ihr habt bewiesen, dass Ihr alle Techniken meistern könnt. \n\nHier sind die übrigen Notizen. Ich weiß, dass sie bei Euch in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72298] = { id = 72298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valdrakkenabkommen", description = "Unterstützt die Tortollaner, indem Ihr 3 Weltquests abschließt.", sourceObjective = "Schließt 3 Weltquests der Tortollaner ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[72299] = { id = 72299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Verzauberkunst, wie?\n\n<Boss Magor sieht sich eine Liste an.>\n\nJa, die können wir brauchen. Keine Erfahrung? Kein Problem! Ich habe hier ein Handbuch, das Euch den Einstieg erleichtern wird. Nehmt Euch etwas Zeit, um Eure Fähigkeiten zu verbessern, dann kann ich Euch vielleicht noch mehr helfen. Willkommen auf den Dracheninseln, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72300] = { id = 72300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Ein Ingenieur! Eure Fähigkeiten sind hier bei der Drachenschuppenexpedition sehr gefragt. Ich habe einige Baupläne und Notizen, die von den Meisteringenieuren von Orgrimmar zusammengestellt wurden. Ich soll sie allen aushändigen, die sich für Ingenieurskunst interessieren. Übt ein wenig, später habe ich vielleicht mehr für Euch, das Euer Handwerk vorantreibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72301] = { id = 72301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Wir brauchen Fachkräfte und Handwerker aller Art für die Expedition. Sogar Juwelenschleifer! Ich weiß nicht viel über Juwelierskunst, aber ein Juwelierskunstmeister hat ein Buch gespendet, das Euch den Einstieg erleichtern wird. Baut Eure Fertigkeiten aus und kommt zu mir zurück. Ich habe dann vielleicht mehr für Euch, das Euch hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[72302] = { id = 72302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Ihr seid also hier, um im neuen Land Bergbau zu betreiben? Tja, hier auf der Expedition werdet Ihr auf jeden Fall Gelegenheit dazu haben. Ich habe hier einen alten Almanach für Bergarbeiter, falls Ihr Eure Fertigkeiten verbessern wollt. Schwingt Eure Spitzhacke ein paar Mal und bekommt ein Gefühl für die Sache, dann kommt wieder zu mir. Ich bin sicher, dass ich noch mehr Bücher und Notizen finde, die Ihr hilfreich findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72303] = { id = 72303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Ah, Ihr seid ein Schneider, sagt Ihr? Gut. Ich kann nicht einmal einen Faden einfädeln, aber ich habe einige Muster hier, die von der letzten Expedition zurückgelassen wurden. Die könnt Ihr zur Übung haben. Wenn Ihr mehr braucht, kommt zu mir zurück, vielleicht habe ich bis dahin wieder etwas für Euch.\n\nWas dem letzten Schneider passiert ist? Es heißt, nachts könnte man ihn immer noch hören... Nein, ich ziehe Euch nur auf. Er ist zu seiner Familie heimgereist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72304] = { id = 72304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Ihr seid schon zurück, Verzauberer? Perfekt! Hier bei der Expedition brauchen wir immer fleißige Arbeiter. Wenn Ihr etwas zu tun braucht, habe ich hier ein Handbuch für Fortgeschrittene für Euch. Weiter mit der guten Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[72305] = { id = 72305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Throm-ka, Ingenieur! Ihr wirkt beschäftigt. Eure Leistungen in der Ingenieurskunst sind nicht an der Drachenschuppenexpedition vorübergegangen! Ich habe fortschrittlichere Pläne, die Ihr ausprobieren könnt. Ihr habt einige wichtige Leute beeindruckt, wie es scheint. Nur immer weiter so, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[72306] = { id = 72306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "{name}! Ihr habt die Drachenschuppenexpedition mit Euren Juwelierskünsten schwer beeindruckt. Wenn die Leute \"Juwelierskunst\" hören, denken sie sofort \"{name}\"! Und ich habe hier genau, was Ihr braucht, um Euren Ruf zu festigen: ein Buch über fortgeschrittene Juwelierskunst. Vielleicht kann es Euch helfen, Euer Handwerk zu meistern!", sourceObjectiveStatus = "unverified-source-field" }
quests[72307] = { id = 72307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Gnolle" }
quests[72308] = { id = 72308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "{name}! Ich bin froh, Euch wohlauf zu sehen. Ich muss zugeben, dass ich mir ein wenig Sorgen um Euch gemacht habe, ganz allein bei der Bergarbeit da draußen in der Wildnis der Dracheninseln. Eure Bergarbeit hat der Drachenschuppenexpedition enorm geholfen, aber wenn Ihr noch hilfreicher für uns sein wollt, kann ich Euch hier diesen Almanach für Fortgeschrittene geben, mit dem Ihr Eure Fertigkeiten verbessern könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72309] = { id = 72309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen der Expedition", sourceObjective = "Willkommen zurück, Schneider. Ich habe gehört, dass Ihr Euch gut anstellt. Viele sagen, Ihr wärt... schnittiger als andere! Entschuldigt, {name}. Ich konnte es mir nicht verkneifen. Wenn Ihr so weitermachen wollt, nehmt diese Muster und Notizen, um Eure Schneiderei der Dracheninseln zu verbessern. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[72310] = { id = 72310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Wissens", sourceObjective = "Ah, Drachenreiter! Ich weiß, dass Ihr ein fähiger Kürschner seid, aber wir Maruuk haben eigene Methoden, die Euch nützlich sein könnten. \n\nUnsere Kürschner haben diese Notizen zusammengestellt, um Euren Fortschritt zu unterstützen. Vielleicht stattet Ihr ihnen einen Besuch ab und teilt Eure Kenntnisse ebenfalls mit ihnen.\n\nUnter Freunden kennt der Himmel keine Geheimnisse!", sourceObjectiveStatus = "unverified-source-field" }
quests[72311] = { id = 72311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Wissens", sourceObjective = "Ah, Drachenreiter! Ich weiß, dass Ihr ein fähiger Alchemist seid, aber wir Maruuk haben eigene Methoden, die Euch nützlich sein könnten. \n\nUnsere Alchemisten haben diese Notizen zusammengestellt, um Euren Fortschritt zu unterstützen. Vielleicht stattet Ihr ihnen einen Besuch ab und teilt Eure Kenntnisse ebenfalls mit ihnen.\n\nUnter Freunden kennt der Himmel keine Geheimnisse!", sourceObjectiveStatus = "unverified-source-field" }
quests[72312] = { id = 72312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Wissens", sourceObjective = "Ah, Drachenreiter! Ich weiß, dass Ihr ein fähiger Schmied seid, aber wir Maruuk haben eigene Methoden, die Euch nützlich sein könnten. \n\nUnsere Schmiede haben diese Notizen zusammengestellt, um Euren Fortschritt zu unterstützen. Vielleicht stattet Ihr ihnen einen Besuch ab und teilt Eure Kenntnisse ebenfalls mit ihnen.\n\nUnter Freunden kennt der Himmel keine Geheimnisse!", sourceObjectiveStatus = "unverified-source-field" }
quests[72313] = { id = 72313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Wissens", sourceObjective = "Ah, Drachenreiter! Ich weiß, dass Ihr ein fähiger Kräuterkundiger seid, aber wir Maruuk haben eigene Methoden, die Euch nützlich sein könnten. \n\nUnsere Kräuterkundigen haben diese Notizen zusammengestellt, um Euren Fortschritt zu unterstützen. Vielleicht stattet Ihr ihnen einen Besuch ab und teilt Eure Kenntnisse ebenfalls mit ihnen.\n\nUnter Freunden kennt der Himmel keine Geheimnisse!", sourceObjectiveStatus = "unverified-source-field" }
quests[72314] = { id = 72314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Geheimnissen", sourceObjective = "{name}, Ihr habt das Herz eines Zentauren... und Ihr habt größere Hingabe für Euer Handwerk bewiesen, als wie je erwartet hätten. \n\nDas letzte Mal, als wir uns über Alchemie unterhalten haben, habe ich eine erste Portion des Wissens unserer Meisterhandwerker mit Euch geteilt. Aber Ihr habt bewiesen, dass Ihr alle Techniken meistern könnt. \n\nHier sind die übrigen Notizen. Ich weiß, dass sie bei Euch in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72315] = { id = 72315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Geheimnissen", sourceObjective = "{name}, Ihr habt das Herz eines Zentauren... und Ihr habt größere Hingabe für Euer Handwerk bewiesen, als wie je erwartet hätten. \n\nDas letzte Mal, als wir uns über Schmiedekunst unterhalten haben, habe ich eine erste Portion des Wissens unserer Meisterhandwerker mit Euch geteilt. Aber Ihr habt bewiesen, dass Ihr alle Techniken meistern könnt. \n\nHier sind die übrigen Notizen. Ich weiß, dass sie bei Euch in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72316] = { id = 72316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Geheimnissen", sourceObjective = "{name}, Ihr habt das Herz eines Zentauren... und Ihr habt größere Hingabe für Euer Handwerk bewiesen, als wie je erwartet hätten.\n\nDas letzte Mal, als wir uns über Kräuterkunde unterhalten haben, habe ich eine erste Portion des Wissens unserer Meisterhandwerker mit Euch geteilt. Aber Ihr habt bewiesen, dass Ihr alle Techniken meistern könnt.\n\nHier sind die übrigen Notizen. Ich weiß, dass sie bei Euch in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72317] = { id = 72317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Geheimnissen", sourceObjective = "{name}, Ihr habt das Herz eines Zentauren... und Ihr habt größere Hingabe für Euer Handwerk bewiesen, als wie je erwartet hätten. \n\nDas letzte Mal, als wir uns über Kürschnerei unterhalten haben, habe ich eine erste Portion des Wissens unserer Meisterhandwerker mit Euch geteilt. Aber Ihr habt bewiesen, dass Ihr alle Techniken meistern könnt. \n\nHier sind die übrigen Notizen. Ich weiß, dass sie bei Euch in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72318] = { id = 72318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen von Iskaara", sourceObjective = "Ah, ein Verzauberer, der eine antike Kunst zu schätzen weiß.\n\nUnsere Vorfahren waren meisterhafte Verzauberer. Da Ihr uns so gut helft, werden wir unser Wissen mit Euch teilen. Wir sind von Feinden umgeben und müssen daher Bestleistungen von allen Mitgliedern unserer Gemeinschaft fordern. Ich hoffe, dass wir Euch ebenfalls dazuzählen können.\n\nHier sind Notizen, mit denen Ihr die Grundlagen erlernen können solltet. Sprecht mit mir, wenn Ihr mehr lernen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72319] = { id = 72319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen von Iskaara", sourceObjective = "Ein Naturliebhaber wie ich! Gut.\n\nAlle Tuskarr respektieren den Lauf der Natur. Kräuterkundige sind in unserer Gemeinschaft hoch angesehen! Wir haben eine lange Tradition, die Gaben des Landes in unseren Ritualen und Arzneien zu verwenden. Unser Kräuterkundeältesten sind sehr erfahren, aber... sie bleiben auch gerne unter sich. Doch sie haben Notizen und Zeichnungen für all jene dagelassen, die ihrem Pfad in die Wildnis folgen wollen. Setzt sie weise ein und kommt wieder zu mir, wenn Ihr mehr lernen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72320] = { id = 72320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen von Iskaara", sourceObjective = "Juwelierskunst? Hm, die Arbeit hat mich immer angesprochen. Wer würde sich nicht von den funkelnden Schätzen der Erde angezogen fühlen?\n\nWie viele andere unseres Volkes, haben wir die Kunst des Juwelenschleifens perfektioniert. Und wir haben unser Wissen für die Zukunft festgehalten. Wenn Ihr uns helfen wollt, Juwelier, können wir unser Wissen miteinander teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72321] = { id = 72321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen von Iskaara", sourceObjective = "Grüße, Lederverarbeiter.\n\nWir Tuskarr sind stolz auf unsere Lederarbeiten. Unsere Kultur nutzt seit vielen Generationen Häute und Felle, um sich vor den Elementen und Verletzungen zu schützen. Ihr werdet nirgendwo bessere Lederarbeiten finden. Weil Ihr uns helfen wollt, werden wir unser Können mit Euch teilen. Ich habe Muster und Notizen hier, die Euch auf den Weg bringen werden, die Lederverarbeitung der Tuskarr zu meistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[72322] = { id = 72322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkswissen von Iskaara", sourceObjective = "Ihr wollt mehr über Kürschnerei lernen? Da seid Ihr zu den richtigen Leuten gekommen!\n\nWir sind stolz auf die Qualität unserer Häute und Felle. Auf unseren Jagden ergattern wie die besten Pelze und unsere Jäger hüten ihre Geheimnisse sorgfältig. Zumindest einige von ihnen. Ich habe hier Notizen von einigen unserer erfahrensten Jäger, die ich mit Euch teilen kann. Damit könnt Ihr anfangen, wie ein Tuskarr zu Kürschnern!", sourceObjectiveStatus = "unverified-source-field" }
quests[72323] = { id = 72323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksmeisterschaft von Iskaara", sourceObjective = "Der aufstrebende Verzauberer kehrt zurück! Habt Ihr Eure ersten Studien gemeistert? Gut!\n\nNormalerweise würdet Ihr nun einen Mentor der Verzauberung zugeteilt bekommen, um Euch anzuleiten. Aber wir leben in schweren Zeiten. Stattdessen habe ich hier weitere Notizen unserer Meisterverzauberer. Mögen sie Euch dienlich sein und möget Ihr sie nutzen, um unserer Gemeinschaft zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72324] = { id = 72324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksmeisterschaft von Iskaara", sourceObjective = "Grüße, Kräuterkundiger! Ich sehe, Ihr seid von Euer Reise durch die Wildnis zurück.\n\nIch habe Gerüchte gehört, dass Euer Können gewachsen ist und Ihr unserer Gemeinschaft sehr geholfen habt. Als Dank habe ich weitere Notizen und Zeichnungen gesammelt, mit denen Ihr Eure Fähigkeiten verbessern könnt. Nutzt sie weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[72325] = { id = 72325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksmeisterschaft von Iskaara", sourceObjective = "Juwelier! Ich bin froh, Euch wiederzusehen.\n\nIch habe Gerüchte gehört, dass Eure Juwelierskunst der unserer talentiertesten Handwerksmeister nahekommt. Ich könnte das nicht beurteilen. Ich kann einen teuren Edelstein nicht von einem Stück Glas unterscheiden! Aber was ich beurteilen kann, ist, dass Euer Mut unserer Gemeinschaft weiterhin eine große Hilfe ist. Als Belohnung habe ich mehr Notizen von unseren Handwerksmeistern gesammelt, die ich Euch geben möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[72326] = { id = 72326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksmeisterschaft von Iskaara", sourceObjective = "Lederer! Es tut gut, Euch zu sehen.\n\nIch schätze, Ihr wollt mehr Geheimnisse unserer Lederverarbeitung erfahren? Hahaha! Natürlich wollt Ihr das. Ich werde sie Euch nicht vorenthalten. Euer Mut hat Euch bei unserem Volk wahre Berühmtheit eingebracht. Hier. Ich habe mehr Muster und Notizen für Euch, mit denen Ihr Euer Handwerk meistern könnt. Eines Tages werde ich Eure Lederarbeiten nicht mehr von unseren eigenen unterscheiden können!", sourceObjectiveStatus = "unverified-source-field" }
quests[72327] = { id = 72327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksmeisterschaft von Iskaara", sourceObjective = "Ah, unser aufstrebender Kürschner ist zurückgekehrt. Ich kann Euren Händen ansehen, dass Ihr hart gearbeitet habt. Ausgezeichnet!\n\nAn einem normalen Tag, in normalen Zeiten, würde ich Euch helfen, einen Meister zu finden, der Euch anleitet. Aber wir befinden uns weder an einem normalen Tag noch in normalen Zeiten, und wir müssen mit dem arbeiten, was wir haben. Bitte, nehmt diese Notizen, mit denen Ihr Euer Handwerk meistern könnt. Durch Eure Arbeit und Kühnheit seid Ihr ein teurer Freund für die Tuskarr geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[72328] = { id = 72328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere wilden, gepanzerten Reittiere", sourceObjective = "Noch einmal Hallo, mein Freund! Glaubt Ihr, ein anderer Ottuk wird eine Bindung mit Euch eingehen? Nun, wir werden sehen.\n\nIch überlasse es Euch und den Ottuks, zu erspüren, ob eine weitere Bindung besteht. Ich muss sagen, dass ein Rudel Ottuks ein furchterregender Anblick ist. Ich habe fast Mitleid mit Euren Gegnern.\n\nIch erinnere Euch daran, dass das Zaumzeug für Ottuks teuer ist, besonders das Kriegspaket. Also, wenn Ihr einen weiteren trainieren möchten, müssen meine Mittrainer und ich um eine stattliche Summe bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72329] = { id = 72329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Ein Schmied, wie? Wenn Ihr Eure Tage am liebsten rußbedeckt verbringt, dann seid Ihr hier richtig.\n\nAber wenn Ihr die Schmiedekunst von unseren Meistern lernen wollt, müsst Ihr Euch anstrengen. Sie haben Notizen für Leute wie Euch, die sich verbessern wollen, hinterlegt. \n\nNehmt sie. Sie sind ein wenig angesengt, aber lesbar. Übt ein wenig, und vielleicht könnt Ihr sie später persönlich treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72330] = { id = 72330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Ihr wollt also die Ingenieurskunst erlernen, wie? Und ich wette, am liebsten von unseren Meisteringenieuren persönlich.\n\nViel Glück. Ihre Zeit und Fähigkeiten werden zu dringend gebraucht, um sie für \"aufstrebende\" Ingenieure aufzuwenden.\n\nIch sage Euch was... Ich habe hier einige ihrer Notizen zur Hand. Vielleicht könnt Ihr ein wenig an den Bauplänen üben, die sie aufgezeichnet haben, Eure Fertigkeit beweisen und ihre Aufmerksamkeit gewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72331] = { id = 72331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Inschriftenkunde? Ein edles Streben... Es erfordert einen scharfen Verstand, eine ruhige Hand und Geduld.\n\nFalls Ihr nach einer Ausbildung sucht, bezweifle ich, dass Ihr Euch bei unseren Inschriftenmeistern beliebt macht, wenn Ihr sie stört. Aber ich habe einige Notizen für alle, die ihre Kunst erlernen wollen. \n\nWenn Ihr mit den Notizen übt, könnt Ihr sie später vielleicht überzeugen, Euch größeres Wissen zuteilwerden zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72332] = { id = 72332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Ihr wollt etwas über Bergbau lernen? Wirklich? Gefällt es Euch, im Dunkeln herumzuirren? Oder gehört Ihr zu diesen Sprengstoffliebhabern?\n\nNein, sagt es mir nicht. Ich will es nicht wirklich wissen. \n\nUnsere Bergbaumeister stecken gerade mitten in der Arbeit, aber ich habe hier einige Notizen, die sie mir für aufstrebende Bergarbeiter hiergelassen haben. Verzeiht die vielen Flecken und Kritzeleien. Ich schätze, es ist nicht so leicht, im Licht einer Kopflampe zu schreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72333] = { id = 72333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Ihr wollt die Schneiderei von unseren Meistern lernen?\n\n<Dothenos betrachtet Euch von oben bis unten und runzelt die Stirn.>\n\nIch würde nicht in Eurem Aufzug mit ihnen sprechen. Hier... ich habe einige Muster, die sie zur Übung für aufstrebende Schneider zusammengestellt haben. Versucht Euch daran, und kommt später noch einmal zu mir... Bestenfalls zieht Ihr Euch bis dahin auch besser an, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72334] = { id = 72334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "Ah, Ihr seid zurückgekehrt! Ich wusste es...\n\nUnsere Inschriftenmeister haben Eure Arbeit gesehen und sind stolz, Euch in ihren Rängen aufzunehmen. Sie haben mir diese sorgfältig ausgewählten Notizen für Euch übergeben, die Eure Studien weiter vorantreiben sollen. \n\nGut gemacht, Inschriftenkundiger!", sourceObjectiveStatus = "unverified-source-field" }
quests[72335] = { id = 72335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "Ihr habt wohl hart gearbeitet, {name}! Das kann ich sehen. Ihr seid etwas blasser als beim letzten Mal... Berufsrisiko, stimmt's?\n\nUnsere Bergbaumeister haben von Eurem Fleiß gehört und Euch weitere ihrer Notizen hinterlegt, die helfen sollen, Eure Fertigkeiten zu verbessern. \n\nWenn Ihr so mit Eurer Arbeit weitermacht, bin ich sicher, dass Ihr Euch bald selbst zu den Meistern zählen könnt!", sourceObjectiveStatus = "unverified-source-field" }
